 * unspoken motives. These summaries are reviewed against each authored bond. */
const SHARED_HISTORY: Readonly<Record<string, string>> = {
  UO: 'Half-siblings. Nineteen years without speaking, over a house neither kept. Civil since the crash.',
  SX: 'Sten taught Xan to swim forty-eight years ago.', AU: 'Schoolmates who are fond of one another.',
  XA: 'Grew up on the same street.', SO: "Sten knew Osvald's father at the harbour.",
  HQ: "Halim blocked Quim's promotion twice; Quim knows this.", HG: 'Worked together for twenty years.',
  GQ: 'Gita was a demanding colleague toward Quim.', DH: 'Dima reported a real structural fault; Halim buried the report. Nobody was hurt. They have not discussed it here.',
  QW: 'Worked together for two overlapping years, on friendly terms.', MT: 'A close bond of thirty years.',
  TV: "Tomás is Vero's uncle. He took his sister's side in a family rupture.", MV: 'Mara has known Vero since she was nine.',
  FM: 'Ferran carried messages between people for years; this was known.', FI: 'Ferran brought Iris into their former circle.',
  MI: 'Mara has blamed Iris for twenty-two years; Iris knows what she is blamed for.', PK: 'Lived in the same building for nine years.',
  KJ: "Juno rode Kes's route; they knew each other in passing.", LP: 'Lior previously owed money to the bakery.',
  CY: "Cato was briefly Yara's clinician.", CN: 'Two doctors who met at conferences, on cordial terms.',
  FH: 'Ferran drew for the yard for one season twenty-odd years ago. They recognised each other in Common on day four.',
  PA: 'Originally from the same region; recognised their accents in the first week after the crash.',
};
export function sharedBondsFor(actor: ResidentId) {
  return BONDS.filter((bond) => bond.from === actor || bond.to === actor).flatMap((bond) => {
    const history = SHARED_HISTORY[`${bond.from}${bond.to}`];
    return history ? [{ other: bond.from === actor ? bond.to : bond.from, history }] : [];
  });
}

// The world, as it actually stands.
//
// Everything the habitat is at a given instant, and nothing else: no rendering,
// no narration, no model. The engine advances this and emits a record of what it
// did; the view reads a snapshot taken from it. Those are the only two ways out.
//
// The whole thing is deterministic. The seed lives in the state and every random
// draw is taken from a stream derived from (seed, day, watch), so a world can be
// replayed from any point and will do exactly what it did the first time. That
// matters more here than anywhere else in the project: a society nobody can replay
// is a society nobody can debug, and this one is supposed to run for years.

import { mulberry32 } from '../random';
import { ROOMS, ROOM_BY_ID, type RoomId } from '../rooms';
import { RESIDENTS, type ResidentId } from '../residents';
import { edges, type Axis } from '../weave';
import { isWalkable, type Point } from '../grid';
import type { HabitatSnapshot } from '../snapshot';
import { createEconomy, type Economy, type MemoryFact } from './economy';
import { initialKnowledge, type KnownFact } from './knowledge';

/** The five slow conditions. Nought is dire, a hundred is fine. They move over
 *  days and weeks, and only matter when they degrade — which is when they start
 *  putting pressure on the person carrying them. */
export const CONDITIONS = ['rested', 'fed', 'well', 'safe', 'accompanied'] as const;
export type Condition = (typeof CONDITIONS)[number];

export type Body = {
  id: ResidentId;
  room: RoomId;
  at: Point;
  condition: Record<Condition, number>;
  /** Charge cells held. The universal commodity, and it leaks. */
  cells: number;
  /** Current urgency. Cognition combines this bounded pressure with unbounded
   *  time since the last thought, so urgency cannot exclude anybody forever. */
  pressure: number;
  /** The day they last had one. */
  thoughtOn: number;
  lastThoughtWatch: number;
  /** Opportunity consumed, including an invalid or unavailable provider. */
  lastAttemptWatch: number;
  lastInteractionWatch: number;
  knownFacts: KnownFact[];
  /** A deliberate visit remains meaningful across watches; urgent needs may interrupt. */
  plan: { room: RoomId; untilWatch: number; reason: string } | null;
  memory: MemoryFact[];
  /** What they are doing this watch, in the present tense. */
  doing: string;
};

export type RoomBody = {
  id: RoomId;
  /** Whether anybody is paying to light it this watch. */
  lit: boolean;
};

export type Reactor = {
  /** Fraction of first-day output. It only ever falls. */
  output: number;
};

export type Happening = {
  day: number;
  watch: number;
  /** Minutes into the day, so the record sorts and reads as a clock. */
  minute: number;
  room: RoomId;
  who: readonly ResidentId[];
  /** What the engine did. Dry, and true by construction. */
  text: string;
  /** For filtering and for the view. */
  kind: 'work' | 'need' | 'meeting' | 'power' | 'note';
};

/** What one person holds towards another, on all six axes. Directed. */
export type AxisMatrix = Map<string, Record<Axis, number>>;

export type WorldState = {
  seed: number;
  day: number;
  watch: number;
  bodies: Record<ResidentId, Body>;
  rooms: Record<RoomId, RoomBody>;
  reactor: Reactor;
  economy: Economy;
  axes: AxisMatrix;
  /** Only the current day's. Everything older belongs in storage, not memory. */
  record: Happening[];
};

/** A stream nobody else is drawing from, derived from where we are in time. */
export function streamFor(state: WorldState, salt: number): () => number {
  return mulberry32(state.seed * 31 + state.day * 977 + state.watch * 13 + salt);
}

export function axisKey(from: ResidentId, to: ResidentId): string {
  return `${from}${to}`;
}

export function held(state: WorldState, from: ResidentId, to: ResidentId): Record<Axis, number> {
  return state.axes.get(axisKey(from, to))!;
}

/** Where the ship's register expects somebody during a working watch. Several of
 *  these send a person somewhere they are no good, which is the point. */
export const POSTED: Record<ResidentId, RoomId> = {
  A: 'records', B: 'hold', C: 'infirmary', D: 'dock', E: 'common',
  F: 'face', G: 'longwalk', H: 'common', I: 'administration', J: 'workshops',
  K: 'dispatch', L: 'hold', M: 'common', N: 'infirmary', O: 'well',
  P: 'common', Q: 'workshops', R: 'hold', S: 'common', T: 'common',
  U: 'infirmary', V: 'garden', W: 'workshops', X: 'face', Y: 'face',
};

/** Which of the eleven residential units somebody sleeps in. Ten in the five
 *  cabins the ship came with, fifteen in the six diggings cut by hand — and who
 *  shares with whom is read off the weave rather than assigned, so a household is
 *  a bond you can point at. */
export const SLEEPS: Record<ResidentId, RoomId> = {
  D: 'cabin1', E: 'cabin1',
  H: 'cabin2', F: 'cabin2',
  G: 'cabin3', C: 'cabin3',
  B: 'cabin4', R: 'cabin4',
  O: 'cabin5', I: 'cabin5',
  M: 'dig1', T: 'dig1', V: 'dig1',
  Q: 'dig2', W: 'dig2', L: 'dig2',
  P: 'dig3', K: 'dig3', J: 'dig3',
  X: 'dig4', S: 'dig4',
  U: 'dig5', A: 'dig5',
  Y: 'dig6', N: 'dig6',
};

function pointKey(point: Point): string {
  return `${point.x}:${point.y}`;
}

/** Every tile where a body can safely be drawn. Places with something underfoot
 *  come first, then the rest of the walkable floor as overflow. Reading order is
 *  deliberate: together with the resident offset it makes placement replayable. */
function standingSpots(room: RoomId): Point[] {
  const { grid, legend } = ROOM_BY_ID[room];
  const supported: Point[] = [];
  const overflow: Point[] = [];
  for (let y = 0; y < grid.length; y += 1) {
    for (let x = 0; x < (grid[y]?.length ?? 0); x += 1) {
      if (!isWalkable(grid, legend, x, y)) continue;
      const point = { x, y };
      if (!isWalkable(grid, legend, x, y + 1)) supported.push(point);
      else overflow.push(point);
    }
  }
  return [...supported, ...overflow];
}

/** Room membership is logical presence, not art capacity. The legacy point is a
 * walkable presentation anchor; a crowded room may reuse an anchor. The observer
 * owns actual sprite occupancy and never sends those positions back to life. */
export function placeInRoom(state: WorldState, id: ResidentId, room: RoomId, preferred?: Point): void {
  const occupied = new Set(
    RESIDENTS
      .map((resident) => state.bodies[resident.id])
      .filter((body) => body.id !== id && body.room === room)
      .map((body) => pointKey(body.at)),
  );
  const spots = standingSpots(room);
  const ordinal = RESIDENTS.findIndex((resident) => resident.id === id);
  const start = spots.length === 0
    ? 0
    : (ordinal * 7 + state.day * 3 + state.watch) % spots.length;
  const definition = ROOM_BY_ID[room];
  let at: Point | undefined = preferred
    && isWalkable(definition.grid, definition.legend, preferred.x, preferred.y)
    && !occupied.has(pointKey(preferred)) ? { ...preferred } : undefined;
  for (let offset = 0; !at && offset < spots.length; offset += 1) {
    const candidate = spots[(start + offset) % spots.length]!;
    if (!occupied.has(pointKey(candidate))) {
      at = candidate;
      break;
    }
  }
  at ??= spots[start];
  if (!at) throw new RangeError(`No presentation anchor exists in ${room}`);
  state.bodies[id].room = room;
  state.bodies[id].at = at;
}

/** Day one hundred, as the engine holds it. Built from the authored content, so
 *  the world the engine advances is the world the documents describe. */
export function genesisState(seed = 1): WorldState {
  const rand = mulberry32(seed);
  const bodies = Object.fromEntries(RESIDENTS.map((r) => {
    const room = POSTED[r.id];
    return [r.id, {
      id: r.id,
      room,
      // Assigned once every body exists so positions never overlap.
      at: { x: -1, y: -1 },
      condition: {
        rested: 60 + Math.floor(rand() * 30),
        fed: 62 + Math.floor(rand() * 30),
        well: 70 + Math.floor(rand() * 26),
        safe: 55 + Math.floor(rand() * 30),
        accompanied: 40 + Math.floor(rand() * 45),
      },
      cells: 8 + Math.floor(rand() * 10),
      pressure: Math.floor(rand() * 20),
      thoughtOn: 100 - Math.floor(rand() * 4),
      lastThoughtWatch: 0, lastAttemptWatch: 0, lastInteractionWatch: 0,
      knownFacts: initialKnowledge(r.id), plan: null,
      memory: [] as MemoryFact[],
      doing: 'at their post',
    } satisfies Body];
  })) as Record<ResidentId, Body>;

  const rooms = Object.fromEntries(ROOMS.map((r) => [
    r.id, { id: r.id, lit: r.id !== 'breach' } satisfies RoomBody,
  ])) as Record<RoomId, RoomBody>;

  const axes: AxisMatrix = new Map();
  for (const e of edges('now')) {
    axes.set(axisKey(e.from, e.to), { ...e.axes });
  }

  const state: WorldState = {
    seed,
    day: 100,
    watch: 1,
    bodies,
    rooms,
    reactor: { output: 0.94 },
    economy: createEconomy(100, Object.values(bodies).reduce((sum, b) => sum + b.cells, 0)),
    axes,
    record: [],
  };
  for (const resident of RESIDENTS) {
    placeInRoom(state, resident.id, POSTED[resident.id]);
    state.bodies[resident.id].lastThoughtWatch = state.bodies[resident.id].thoughtOn * 4;
    state.bodies[resident.id].lastAttemptWatch = state.bodies[resident.id].lastThoughtWatch;
  }
  return state;
}

/** Clamp anything that is meant to be a nought-to-a-hundred quantity. */
export function bounded(v: number): number {
  return Math.max(0, Math.min(100, v));
}

export function nudge(
  state: WorldState, from: ResidentId, to: ResidentId, axis: Axis, by: number,
): void {
  const set = state.axes.get(axisKey(from, to));
  if (!set) return;
  set[axis] = bounded(set[axis] + by);
}

/** Positive affinity in both directions, discounted by resentment. */
export function between(state: WorldState, a: ResidentId, b: ResidentId): number {
  const there = held(state, a, b);
  const back = held(state, b, a);
  // Resentment and an unpaid debt are intensity, not reasons to seek company.
  const affinity = (axes: Record<Axis, number>) => (axes.affection + axes.trust + axes.admiration) / 3 - axes.resentment * 0.35;
  return Math.max(0, (affinity(there) + affinity(back)) / 2);
}

/** The world as the window is allowed to see it.
 *
 *  The only way out. The view has read a snapshot since the day it was written,
 *  which is what makes wiring a live world into it one function rather than a
 *  rewrite — and what will let the simulation move to a scheduler somewhere else
 *  without the frontend noticing. */
export function snapshotFrom(state: WorldState): HabitatSnapshot {
  const people = RESIDENTS.map((r) => {
    const b = state.bodies[r.id];
    return { id: r.id, room: b.room, at: b.at, doing: b.doing };
  });
  const occupants = new Map<RoomId, ResidentId[]>();
  for (const p of people) {
    const list = occupants.get(p.room) ?? [];
    list.push(p.id);
    occupants.set(p.room, list);
  }
  return {
    day: state.day,
    watch: Math.min(4, Math.max(1, state.watch)) as 1 | 2 | 3 | 4,
    power: state.reactor.output,
    rooms: ROOMS.map((r) => ({
      id: r.id,
      occupants: occupants.get(r.id) ?? [],
      lit: state.rooms[r.id].lit,
    })),
    people,
    // Closing watch IV advances the world to the next day while retaining the
    // completed record long enough for the persistence adapter to archive it.
    // Never label those previous-day entries as the new day's live record.
    record: state.record.filter((e) => e.day === state.day).map((e) => ({
      minute: e.minute, room: e.room, who: e.who, text: e.text,
    })),
  };
}

// The world advancing.
//
// Four watches to a day, inherited from the ship. Inside a watch the engine does
// not run a script: it lets everybody act, and what comes out is whatever their
// bodies, their posts and the people standing next to them make likely. The
// record is emitted from state that actually changed, never from a description of
// something that was supposed to have happened.
//
// There is no model here and there is deliberately a hole where one goes. The
// `choose` function is the seam: today it is a routine policy that reads needs and
// proximity, and a scarce oracle will one day be asked for the same thing — a verb
// and a target — for whichever handful of people have the most pressure. Both
// answers go through `attempt`, which is what stops either of them from asserting
// a fact into the world.

import { ROOM_BY_ID, ROOMS, type RoomId } from '../rooms';
import { RESIDENTS, RESIDENT_BY_ID, type ResidentId } from '../residents';
import {
  CONDITIONS, POSTED, SLEEPS, between, bounded, streamFor,
  type Happening, type WorldState,
} from './state';
import { closeEconomyDay, outstanding, remember } from './economy';
import { attempt, decodeIntentFor, VERBS, type Intent, type VerbName, type Outcome } from './verbs';
import { PLANNABLE_VERBS, type PhysicalObservation, type PlannedAction } from '../society/types';

export type SocietyWatchOptions = {
  plans: Partial<Record<ResidentId, PlannedAction>>;
  /** Called once per resident, with the pre-advance day/watch, after their real
   * action. The caller persists these observations with the resulting world. */
  onAction?: (observation: PhysicalObservation) => void;
};

/** How fast the five conditions fall over one watch, with nobody doing anything
 *  about them. Slow: these are meant to bite over days, not hours. */
const DECAY = {
  rested: 5, fed: 9, well: 0.6, safe: 1, accompanied: 5,
} as const satisfies Record<(typeof CONDITIONS)[number], number>;

/** Watch four is the one nobody is posted for. It is when the habitat is
 *  quietest, cheapest to run, and when the people who live at night are awake. */
const NIGHT = 4;

/** Watches two and three are when the habitat eats.
 *
 *  Not decoration, and not a convenience: without it the Dock is four watches
 *  from the only food in the habitat, so anybody posted there could either work
 *  or eat and not both, and the engine quietly starved them. A shared mealtime
 *  fixes the physics and is the truer model anyway — it is also what makes the
 *  Common the social heart, because it is the one thing that puts everybody in
 *  one room at the same time every single day. */
const MEALS = new Set([2, 3]);

/** What the reactor loses a day. Small, relentless, and the reason every argument
 *  about allocation will eventually get worse. */
const DECLINE = 0.00022;


/** What it costs to keep a room lit for a day. Surface spaces need no allocation
 *  while the Workshops power bay and the Well keep their inherited machinery. */
function upkeep(room: RoomId): number {
  if (ROOM_BY_ID[room].side === 'surface') return 0;
  if (room === 'well' || room === 'workshops') return 18;
  return 8;
}

/** A watch includes travel through the habitat; visual corridors are archived
 * artwork, not time or capacity constraints on a resident's agency. */
function stepToward(from: RoomId, to: RoomId): RoomId | null {
  return from === to || to === 'breach' ? null : to;
}

function personalRetreat(id: ResidentId): RoomId {
  const words = `${RESIDENT_BY_ID[id].wants} ${RESIDENT_BY_ID[id].was}`.toLowerCase();
  if (/music|song|dance/.test(words)) return 'salon';
  if (/book|read|history|write/.test(words)) return 'library';
  if (/plant|grow|garden/.test(words)) return 'winter';
  if (/family|home|child/.test(words)) return 'hearth';
  const rooms: RoomId[] = ['study', 'parlour', 'games', 'projection', 'sodabar', 'yard'];
  return rooms[(id.charCodeAt(0) - 65) % rooms.length]!;
}

/**
 * What somebody does with this watch.
 *
 * This is the seam. It reads only the state a person could actually perceive —
 * their own body, the room they are in, who is standing in it — and returns an
 * intent, which the engine is then free to refuse. When cognition arrives it
 * replaces this for the handful of people with the most pressure, and everybody
 * else keeps running on exactly this, for free.
 */
export function choose(state: WorldState, id: ResidentId, roll: () => number): Intent {
  const b = state.bodies[id];
  // People can arrange contact during a watch regardless of display position.
  const here = RESIDENTS.map((resident) => resident.id).filter((other) => other !== id);
  const stock = state.economy.stock;
  const night = state.watch === NIGHT;
  const toward = (room: RoomId, verb: VerbName): Intent => {
    const hop = stepToward(b.room, room);
    return hop ? { verb: 'go', actor: id, room: hop } : { verb, actor: id };
  };
  const feasible = (verb: VerbName, target?: ResidentId): Intent | undefined => {
    const intent: Intent = { verb, actor: id, ...(target ? { target } : {}) };
    return !VERBS[verb].requires?.(state, intent) && b.cells >= (VERBS[verb].cost ?? 0) ? intent : undefined;
  };
  // Hunger has an actual supply chain. An empty plate asks for production,
  // never an impossible 'eat' repeated indefinitely beside an empty store.
  const findFood = (): Intent => {
    if (stock.water < (stock.meals < 1 && stock.produce < 4 ? 2 : 1)) return toward('well', 'clean');
    if (stock.meals >= 1) return toward('common', b.cells >= 0.5 || b.condition.fed < 28 ? 'eat' : 'work');
    if (stock.produce >= 4) return toward('common', 'cook');
    return toward('garden', 'grow');
  };
  if (b.condition.fed < 18) return findFood();
  if (b.condition.rested < 15) return { verb: 'sleep', actor: id };
  if (b.condition.fed < 28) return findFood();
  // A six-hour night is enough to cross the entire connected habitat and sleep.
  // Health and reserve work must not trap somebody halfway home each night.
  if (night) return toward(SLEEPS[id], 'sleep');
  if (MEALS.has(state.watch) && b.condition.fed < 62) return findFood();
  if (b.condition.well < 42) return stock.water >= 2 ? toward('well', 'wash') : toward('well', 'clean');
  if (b.condition.rested < 35) return { verb: 'rest', actor: id };

  // A remembered agreement competes with a new conversation. A borrower first
  // seeks their lender once they can afford a partial repayment.
  const owed = outstanding(state, id).find((debt) => b.cells >= Math.min(2, debt.remaining) + 2);
  if (owed) {
    return { verb: 'repay', actor: id, target: owed.lender };
  }
  if (b.condition.safe < 45) {
    const provider = here.filter((other) => feasible('trade', other))
      .sort((a, c) => state.bodies[a].cells - state.bodies[c].cells)[0];
    if (provider) return { verb: 'trade', actor: id, target: provider };
    const repair = feasible('repair');
    if (repair) return repair;
    return { verb: 'rest', actor: id };
  }
  // Communal shortage is visible and actionable. Specialised posts normally
  // cover reserves; anybody can lend a hand when the reserve becomes critical.
  if (stock.water < 40) return toward('well', 'clean');
  if (stock.produce < 8) return stock.water >= 2 ? toward('garden', 'grow') : toward('well', 'clean');
  if (stock.meals < 24) return stock.produce >= 4 ? toward('common', 'cook') : findFood();
  if (stock.materials < 4) return toward('face', 'dig');

  const inNeed = here.filter((other) => state.bodies[other].cells < 4)
    .sort((a, c) => state.bodies[a].cells - state.bodies[c].cells);
  for (const other of inNeed) {
    // Affection favours a gift; a less close but trusted pair can agree a loan.
    const mine = state.axes.get(`${id}${other}`)!;
    const offer = mine.affection >= 45 ? feasible('give', other) : feasible('lend', other);
    if (offer) return offer;
  }
  const willing = here.filter((other) => feasible('accompany', other));
  if (b.condition.accompanied < 40 && willing.length) {
    return { verb: 'accompany', actor: id, target: pickCompany(state, id, willing, roll) };
  }
  const struggling = here.filter((other) => Math.min(state.bodies[other].condition.safe, state.bodies[other].condition.accompanied) < 28)
    .sort((a, c) => state.bodies[a].condition.safe - state.bodies[c].condition.safe)[0];
  if (struggling && feasible('console', struggling) && between(state, id, struggling) > 26) return { verb: 'console', actor: id, target: struggling };

  const stamp = state.day * 4 + state.watch - 1;
  if (b.plan && b.plan.untilWatch >= stamp) {
    if (b.room !== b.plan.room) return toward(b.plan.room, 'observe');
    return b.condition.rested < 65 ? { verb: 'rest', actor: id } : { verb: 'observe', actor: id };
  }
  // Once today's duty is covered, a personal visit is a choice with an actual
  // destination. Needs and outstanding agreements still take precedence.
  if (state.economy.workCredits[id] >= 2 && state.watch === 3) return toward(personalRetreat(id), 'rest');
  const post = POSTED[id];
  if (b.room !== post) return toward(post, 'work');
  // A duty produces only what can be stored and is actually needed.
  const byRoom: Partial<Record<RoomId, VerbName>> = {
    face: stock.materials < 28 ? 'dig' : 'work',
    garden: stock.produce < 64 ? 'grow' : 'work',
    common: stock.meals < 64 && stock.produce >= 4 ? 'cook' : 'work',
    workshops: state.economy.maintenance < 88 && feasible('repair') ? 'repair' : 'charge',
    well: stock.water < 120 ? 'clean' : 'work', infirmary: 'inspect', records: 'note',
  };
  const duty = byRoom[post] ?? 'work';
  // Scarce stock and actual repairs take precedence over idle conversation.
  if (duty !== 'work' && duty !== 'inspect' && duty !== 'note' && duty !== 'charge') {
    const intent = feasible(duty);
    if (intent) return intent;
  }
  if (willing.length && roll() < 0.36) {
    const conversation = talkTo(state, id, willing, roll);
    if (!VERBS[conversation.verb].requires?.(state, conversation)) return conversation;
  }
  return feasible(duty) ?? { verb: 'work', actor: id };
}

/** Who, out of the people in this room.
 *
 *  Weighted by what is already between them, but never simply the strongest:
 *  taking the maximum meant Gita talked to Quim every single evening for a
 *  fortnight and met nobody else, so the weave calcified on day one and the
 *  design's whole claim that bonds form was quietly false. The floor is what
 *  gives a stranger a chance. */
function pickCompany(
  state: WorldState, id: ResidentId, here: ResidentId[], roll: () => number,
): ResidentId {
  const weights = here.map((o) => 8 + between(state, id, o) ** 1.5 / 12);
  const total = weights.reduce((n, w) => n + w, 0);
  let draw = roll() * total;
  for (let i = 0; i < here.length; i += 1) {
    draw -= weights[i]!;
    if (draw <= 0) return here[i]!;
  }
  return here[here.length - 1]!;
}

/** Which of the people in this room, and in what register. What is already
 *  between two people decides the register, which is why the weave compounds. */
function talkTo(
  state: WorldState, id: ResidentId, here: ResidentId[], roll: () => number,
): Intent {
  const target = pickCompany(state, id, here, roll);
  const mine = state.axes.get(`${id}${target}`)!;
  const r = roll();
  if (mine.resentment > 55 && r < 0.5) return { verb: 'argue', actor: id, target };
  if (mine.trust >= 55 && r < 0.16) return { verb: 'confide', actor: id, target };
  if (state.axes.get(`${target}${id}`)!.admiration > 55 && r < 0.3) return { verb: 'teach', actor: id, target };
  if (mine.admiration > 55 && r < 0.3) return { verb: 'ask', actor: id, target };
  if (mine.affection > 50 && r < 0.5) return { verb: 'joke', actor: id, target };
  if (r < 0.3) return { verb: 'listen', actor: id, target };
  if (r < 0.55) return { verb: 'ask', actor: id, target };
  return { verb: 'speak', actor: id, target };
}

/** A short phrase for what somebody is doing, for the view to show. */
function doingFor(intent: Intent, ok: boolean): string {
  if (!ok) return 'at a loose end';
  switch (intent.verb) {
    case 'go': return 'on their way somewhere';
    case 'sleep': return 'asleep';
    case 'rest': return 'sitting down for a bit';
    case 'eat': return 'eating';
    case 'dig': return 'cutting rock';
    case 'grow': return 'in among the trays';
    case 'cook': return 'cooking';
    case 'charge': return 'at the racks';
    case 'give': return 'sharing a few charge cells';
    case 'lend': return 'agreeing a small loan';
    case 'repay': return 'returning borrowed cells';
    case 'trade': return 'paying for a repair';
    case 'work': return 'working at their post';
    case 'clean': return 'keeping the water and rooms usable';
    case 'wash': return 'washing and recovering';
    case 'inspect': return 'checking the room';
    case 'observe': return 'watching quietly';
    case 'repair': return 'fixing something';
    case 'note': return 'writing something down';
    case 'console': return 'sitting with somebody who needs it';
    case 'argue': return 'in the middle of an argument';
    case 'confide': return 'saying something they have not said before';
    default: return 'talking';
  }
}

function assertCognitionActor(state: WorldState, cognition?: Readonly<Intent>): void {
  if (cognition
    && !Object.prototype.hasOwnProperty.call(state.bodies, cognition.actor)) {
    throw new TypeError(`Unknown cognition actor: ${String(cognition.actor)}`);
  }
}

function assertSocietyActors(state: WorldState, society?: SocietyWatchOptions): void {
  for (const [actor, step] of Object.entries(society?.plans ?? {})) {
    if (!step || !Object.hasOwn(state.bodies, actor) || step.intent.actor !== actor) throw new TypeError('Invalid planned actor');
    const { actor: subject, ...raw } = step.intent;
    if (!decodeIntentFor(subject, raw).ok || !(PLANNABLE_VERBS as readonly string[]).includes(raw.verb)) throw new TypeError('Invalid planned action');
  }
}

const NEGOTIATED_ROUTINES = new Set<VerbName>(['give', 'lend', 'trade', 'speak', 'ask', 'listen', 'joke', 'argue', 'confide', 'greet', 'flirt', 'teach']);
/** The old policy remains available to legacy callers. With independent minds,
 * it cannot invent dialogue or accept a financial exchange for a second actor. */
function routineFor(state: WorldState, id: ResidentId, roll: () => number, society?: SocietyWatchOptions): Intent {
  const proposed = choose(state, id, roll);
  if (!society || !NEGOTIATED_ROUTINES.has(proposed.verb)) return proposed;
  if (proposed.verb === 'trade' && !VERBS.repair.requires?.(state, { actor: id, verb: 'repair' })) return { actor: id, verb: 'repair' };
  return { actor: id, verb: state.bodies[id].condition.rested < 60 ? 'rest' : 'observe' };
}

/** Plan travel follows the authored topology. All hops fit within the existing
 * six-hour watch; crossing an opening is not another productive work action. */
function travelForPlan(state: WorldState, actor: ResidentId, destination: RoomId): Outcome {
  const start = state.bodies[actor].room;
  if (destination === 'breach' || !Object.hasOwn(ROOM_BY_ID, destination)) return { ok: false, refused: 'planned destination is inaccessible' };
  if (start === destination) return { ok: true };
  const queue: RoomId[] = [start], previous = new Map<RoomId, RoomId | null>([[start, null]]);
  for (let i = 0; i < queue.length && !previous.has(destination); i += 1) {
    for (const next of ROOM_BY_ID[queue[i]!].connects) {
      if (next === 'breach' || previous.has(next)) continue;
      previous.set(next, queue[i]!); queue.push(next);
    }
  }
  if (!previous.has(destination)) return { ok: false, refused: 'no connected route to planned destination' };
  const path: RoomId[] = [];
  for (let room: RoomId | null = destination; room !== start; room = previous.get(room!)!) path.unshift(room!);
  for (const room of path) {
    const moved = attempt(state, { actor, verb: 'go', room });
    if (!moved.ok) return moved;
  }
  return { ok: true };
}

function urgentPlanInterruption(state: WorldState, actor: ResidentId): string | undefined {
  const c = state.bodies[actor].condition;
  if (c.fed < 18) return 'Critical hunger requires food or its missing supplies';
  if (c.rested < 15) return 'Exhaustion requires sleep';
  if (c.fed < 28) return 'Hunger requires food or its missing supplies';
  if (c.well < 20) return 'Poor health requires washing or clean water';
  return undefined;
}

/** One watch. Everybody acts once, in an order that changes with the day so
 *  nobody is permanently first through the door. */
export function advanceWatch(
  state: WorldState, cognition?: Readonly<Intent>, attemptedActor?: ResidentId, onDecision?: (outcome: Outcome) => void,
  society?: SocietyWatchOptions,
): WorldState {
  assertCognitionActor(state, cognition);
  assertSocietyActors(state, society);
  const roll = streamFor(state, 7);
  const order = RESIDENTS.map(({ id }) => ({ id, priority: state.bodies[id].pressure + roll() * 40 }))
    .sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id))
    .map(({ id }) => id);

  if (cognition) { order.splice(order.indexOf(cognition.actor), 1); order.unshift(cognition.actor); }
  if (attemptedActor ?? cognition?.actor) {
    const subject = state.bodies[(attemptedActor ?? cognition!.actor)];
    subject.lastAttemptWatch = state.day * 4 + state.watch - 1;
  }
  const emitted: Happening[] = [];
  let slot = 0;
  for (const id of order) {
    // A watch is six hours and the habitat is a hundred and twenty-six metres
    // long. Walking to the next room is minutes, not a shift — so a person gets
    // to reach where they are going and then do something there. Charging a
    // whole watch per doorway collapsed the place into a commute: everybody
    // spent every watch in transit and nobody ever arrived at their post.
    const planned = society?.plans[id];
    const interrupted = planned ? urgentPlanInterruption(state, id) : undefined;
    const injected = !planned && cognition?.actor === id ? cognition : undefined;
    let intent: Intent = planned && !interrupted ? { ...planned.intent } : injected ? { ...injected } : routineFor(state, id, roll, society);
    let outcome: Outcome;
    if (planned && !interrupted) {
      const destination = intent.verb === 'go' ? intent.room : planned.at;
      outcome = destination ? travelForPlan(state, id, destination) : { ok: true };
      if (outcome.ok && intent.verb !== 'go') outcome = attempt(state, intent);
      else if (!intent.room && intent.verb === 'go') outcome = { ok: false, refused: 'nowhere named' };
    } else if (planned && interrupted?.startsWith('Poor health')) {
      intent = { actor: id, verb: state.economy.stock.water >= 2 ? 'wash' : 'clean' };
      outcome = travelForPlan(state, id, 'well');
      if (outcome.ok) outcome = attempt(state, intent);
    } else outcome = attempt(state, intent);
    for (let hops = 0; !injected && (!planned || interrupted) && hops < ROOMS.length && outcome.ok && intent.verb === 'go'; hops += 1) {
      intent = routineFor(state, id, roll, society);
      outcome = attempt(state, intent);
    }
    const b = state.bodies[id];
    society?.onAction?.({ actor: id, day: state.day, watch: state.watch, intent: { ...intent }, outcome: structuredClone(outcome),
      actualRoom: b.room, ...(planned ? { stepId: planned.stepId } : {}), ...(interrupted ? { interrupted } : {}) });
    // A thought happened even when the world refused what it proposed.
    if (injected) {
      b.thoughtOn = state.day;
      b.lastThoughtWatch = state.day * 4 + state.watch - 1;
      b.lastAttemptWatch = b.lastThoughtWatch;
      if (outcome.ok && intent.verb === 'go' && intent.room) b.plan = { room: intent.room, untilWatch: b.lastThoughtWatch + 2, reason: 'deliberate visit' };
      onDecision?.(outcome);
    }
    if (b.plan && b.plan.untilWatch < state.day * 4 + state.watch - 1) b.plan = null;
    if (!outcome.ok) remember(state, id, { kind: intent.verb, ...(intent.target ? { other: intent.target } : {}), outcome: outcome.refused ?? 'refused' });
    if ((injected || planned) && !outcome.ok) emitted.push({ day: state.day, watch: state.watch, minute: (state.watch - 1) * 360 + 1,
      room: b.room, who: [id], kind: 'note', text: `${RESIDENT_BY_ID[id].name.split(' ')[0]} tried ${intent.verb}: ${outcome.refused ?? 'refused'}.` });
    if (interrupted) emitted.push({ day: state.day, watch: state.watch, minute: (state.watch - 1) * 360 + 2,
      room: b.room, who: [id], kind: 'note', text: `${RESIDENT_BY_ID[id].name.split(' ')[0]}'s planned activity was interrupted: ${interrupted.toLowerCase()}.` });
    b.doing = doingFor(intent, outcome.ok);
    // A world that says no to somebody is a world they have to think about.
    b.pressure = bounded(b.pressure + (outcome.ok ? -1 : 6));
    if (outcome.happening) {
      emitted.push({
        ...outcome.happening,
        day: state.day,
        watch: state.watch,
        minute: (state.watch - 1) * 360 + Math.floor((slot / order.length) * 340) + 8,
      });
    }
    slot += 1;
  }

  // Bodies run down whatever anybody did about it.
  for (const r of RESIDENTS) {
    const b = state.bodies[r.id];
    for (const key of CONDITIONS) {
      b.condition[key] = bounded(b.condition[key] - DECAY[key]);
    }
    if (b.condition.fed < 18 || b.condition.rested < 12) {
      b.condition.well = bounded(b.condition.well - 3);
      b.pressure = bounded(b.pressure + 5);
    }
  }

  state.record.push(...emitted.sort((a, b) => a.minute - b.minute));
  state.watch += 1;
  return state;
}

/** Close a completed fourth watch: power, light and charge are daily books, not
 *  another action. Both the batch runner and the scheduler use this exact path. */
function closeDay(state: WorldState): void {
  // The reactor makes less than it did yesterday, and it will make less again.
  state.reactor.output = Math.max(0, state.reactor.output - DECLINE);
  const budget = Math.round(state.reactor.output * 1000);

  // Rooms are lit in the order they are needed, until the budget runs out. The
  // last ones on the list go dark, and nobody has agreed what the order is.
  const priority: RoomId[] = [
    'well', 'common', 'kitchen', 'stalls', 'washroom',
    'administration', 'dispatch', 'archive', 'records',
    'study', 'sparebedroom', 'parlour', 'projection', 'winter',
    'games', 'infirmary', 'workshops', 'maintenance',
    'row', 'longwalk',
    'camp', 'garden', 'sheltergate', 'yard',
    // Homes share the reactor allocation, after the essential common spaces.
    'dig1', 'dig2', 'dig3', 'dig4', 'dig5', 'dig6',
    'cabin1', 'cabin2', 'cabin3', 'cabin4', 'cabin5',
    'hold', 'dock', 'bridge', 'face',
  ];
  let left = budget;
  const wentDark: RoomId[] = [];
  for (const id of Object.keys(state.rooms) as RoomId[]) state.rooms[id].lit = false;
  // New catalogue rooms must never be omitted from the allocator.
  for (const id of [...priority, ...ROOMS.map((room) => room.id).filter((id) => id !== 'breach' && !priority.includes(id))]) {
    const cost = upkeep(id);
    if (left >= cost) { left -= cost; state.rooms[id].lit = true; } else wentDark.push(id);
  }
  state.rooms.breach.lit = false;

  // What is left over is minted as charge and goes to whoever worked. Cells leak,
  // so nobody's pile is a plan.
  closeEconomyDay(state, left);
  for (const { id } of RESIDENTS) {
    const b = state.bodies[id];
    b.pressure = bounded(b.pressure + (state.day - b.thoughtOn > 3 ? 4 : 0));
  }

  state.record.push({
    day: state.day, watch: 4, minute: 1430,
    room: 'workshops', who: ['J'],
    text: `Reactor at ${state.reactor.output.toFixed(4)} of first-day output.`
      + (wentDark.length ? ` ${wentDark.length} rooms unlit for want of power.` : ''),
    kind: 'power',
  });

  state.record.sort((a, b) => a.minute - b.minute);
  state.day += 1;
  state.watch = 1;
}

/** Advance exactly one scheduled watch, closing the books after watch IV.
 *
 * Unlike `advanceWatch`, this is a clock primitive: the previous day's record is
 * cleared when watch I begins and completing watch IV rolls the world forward. */
export function advanceScheduledWatch(
  state: WorldState, cognition?: Readonly<Intent>, attemptedActor?: ResidentId, onDecision?: (outcome: Outcome) => void,
  society?: SocietyWatchOptions,
): WorldState {
  assertCognitionActor(state, cognition);
  assertSocietyActors(state, society);
  if (!Number.isInteger(state.watch) || state.watch < 1 || state.watch > NIGHT) {
    throw new RangeError(`Cannot schedule invalid watch ${state.watch}`);
  }
  if (state.watch === 1) { state.record = []; state.economy.events = []; }
  advanceWatch(state, cognition, attemptedActor, onDecision, society);
  if (state.watch === NIGHT + 1) closeDay(state);
  return state;
}

/** One day: four watches, then the books. */
export function advanceDay(state: WorldState): WorldState {
  state.record = [];
  state.economy.events = [];
  state.watch = 1;
  for (let i = 0; i < 4; i += 1) advanceWatch(state);
  closeDay(state);
  return state;
}

/** Run a stretch of days, keeping every day's record rather than only the last.
 *  Used for burn-in and for tests; the live world keeps one day in memory. */
export function run(state: WorldState, days: number): { state: WorldState; log: Happening[] } {
  const log: Happening[] = [];
  for (let i = 0; i < days; i += 1) {
    advanceDay(state);
    log.push(...state.record);
  }
  return { state, log };
}

// What a person can do, and what it costs them.
//
// A verb is engine code, not narration. Each one carries physical preconditions —
// where you are, what you hold, who is present, what power there is — and a
// deterministic effect. Whoever is choosing, whether that is the routine policy
// or a model, only ever names a verb and a target. **The engine validates and
// executes.** Nothing that says it happened makes it happen.
//
// This is the working subset: the verbs a day is made of. The catalogue is a flat
// table on purpose, so the rest of the hundred and ten are additions rather than
// changes — a new verb is a new row, and nothing else moves.

import { ROOM_BY_ID, type RoomId } from '../rooms';
import { RESIDENT_BY_ID, type ResidentId } from '../residents';
import {
  bounded, nudge, placeInRoom, type Body, type Condition, type Happening, type WorldState,
} from './state';
import { CAPACITY, acceptsHelp, outstanding, recordWork, remember, economicAccounts, recordEconomicChange, mechanized, yieldFor } from './economy';
import { FACTS } from './knowledge';

export type VerbFamily =
  | 'body' | 'objects' | 'work' | 'talk' | 'affection' | 'commitment' | 'knowledge';

export type Intent = {
  verb: VerbName;
  actor: ResidentId;
  /** Where the verb wants to happen, for the ones that move somebody. */
  room?: RoomId;
  /** Who it is aimed at. */
  target?: ResidentId;
  /** Explicit knowledge to share; generic conversation never reveals a secret. */
  fact?: string;
};

export type IntentDecodeResult =
  | { ok: true; intent: Intent }
  | { ok: false; error: string };

export type Outcome = {
  ok: boolean;
  /** Why not, when it did not. Kept because a refused intent is data: it is
   *  pressure, and pressure is what buys a person a thought. */
  refused?: string;
  happening?: Omit<Happening, 'day' | 'watch' | 'minute'>;

};

export type Verb = {
  name: string;
  family: VerbFamily;
  /** Charge cells the actor spends. Most things are free; making things is not. */
  cost?: number;
  /** Whether the actor must be somewhere in particular. */
  requires?: (state: WorldState, intent: Intent) => string | null;
  run: (
    state: WorldState, intent: Intent,
  ) => Omit<Happening, 'day' | 'watch' | 'minute'> | null;
};

const CATALOGUE = [
  'go', 'rest', 'sleep', 'eat', 'drink', 'wash',
  'work', 'dig', 'grow', 'cook', 'clean', 'inspect', 'repair', 'charge',
  'speak', 'ask', 'listen', 'joke', 'argue', 'confide',
  'greet', 'accompany', 'console', 'avoid', 'seek out', 'flirt',
  'observe', 'note', 'teach', 'give', 'lend', 'repay', 'trade',
] as const;
export type VerbName = (typeof CATALOGUE)[number];

const INTENT_FIELDS = new Set(['verb', 'room', 'target', 'fact']);
const TARGET_VERBS = new Set<VerbName>(['speak', 'ask', 'listen', 'joke', 'argue', 'confide', 'greet', 'accompany', 'console', 'avoid', 'seek out', 'flirt', 'teach', 'give', 'lend', 'repay', 'trade']);

function hasOwn(value: object, key: PropertyKey): boolean {
  return Object.prototype.hasOwnProperty.call(value, key);
}

/** Decode a model proposal without ever letting the model choose who is acting.
 *
 * This validates only the protocol boundary: known identifiers and no hidden
 * fields. Whether the proposal is possible in the current world remains solely
 * `attempt`'s decision. */
export function decodeIntentFor(actor: unknown, raw: unknown): IntentDecodeResult {
  if (typeof actor !== 'string' || !hasOwn(RESIDENT_BY_ID, actor)) {
    return { ok: false, error: 'unknown actor' };
  }
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    return { ok: false, error: 'intent must be an object' };
  }
  const candidate = raw as Record<string, unknown>;
  const unexpected = Object.keys(candidate).find((key) => !INTENT_FIELDS.has(key));
  if (unexpected) return { ok: false, error: `unexpected field: ${unexpected}` };
  if (!hasOwn(candidate, 'verb') || typeof candidate.verb !== 'string'
    || !(CATALOGUE as readonly string[]).includes(candidate.verb)) {
    return { ok: false, error: 'unknown verb' };
  }
  if (hasOwn(candidate, 'room')
    && (typeof candidate.room !== 'string' || !hasOwn(ROOM_BY_ID, candidate.room))) {
    return { ok: false, error: 'unknown room' };
  }
  if (hasOwn(candidate, 'target')
    && (typeof candidate.target !== 'string' || !hasOwn(RESIDENT_BY_ID, candidate.target))) {
    return { ok: false, error: 'unknown target' };
  }

  const verb = candidate.verb as VerbName;
  if (verb === 'go' && !hasOwn(candidate, 'room')) return { ok: false, error: 'go needs a room' };
  if (TARGET_VERBS.has(verb) && !hasOwn(candidate, 'target')) return { ok: false, error: 'this verb needs a target' };
  if (hasOwn(candidate, 'room') && verb !== 'go') return { ok: false, error: 'room is only valid for go' };
  if (hasOwn(candidate, 'target') && !TARGET_VERBS.has(verb)) return { ok: false, error: 'target is not valid for this verb' };
  if (hasOwn(candidate, 'fact') && (!['confide', 'teach'].includes(verb) || typeof candidate.fact !== 'string' || candidate.fact.length < 1 || candidate.fact.length > 100)) {
    return { ok: false, error: 'invalid knowledge field' };
  }
  const intent: Intent = {
    actor: actor as ResidentId,
    verb: candidate.verb as VerbName,
  };
  if (hasOwn(candidate, 'room')) intent.room = candidate.room as RoomId;
  if (hasOwn(candidate, 'target')) intent.target = candidate.target as ResidentId;
  if (hasOwn(candidate, 'fact')) intent.fact = candidate.fact as string;
  return { ok: true, intent };
}

function body(state: WorldState, id: ResidentId): Body {
  return state.bodies[id];
}

function condition(b: Body, key: Condition, by: number): void {
  b.condition[key] = bounded(b.condition[key] + by);
}

function first(name: ResidentId): string {
  return RESIDENT_BY_ID[name].name.split(' ')[0]!;
}

/** Presence is a consequence of an activity, not a pixel prerequisite. The
 * six-hour watch includes arranging and reaching a willing counterpart. */
function arrive(state: WorldState, id: ResidentId, room: RoomId): void {
  placeInRoom(state, id, room);
}

function together(state: WorldState, intent: Intent): string | null {
  if (!intent.target) return 'nobody named';
  if (intent.target === intent.actor) return 'alone';
  if (intent.verb === 'avoid' || intent.verb === 'repay') return null;
  const recipient = body(state, intent.target);
  if (['give', 'lend'].includes(intent.verb)) return null; // receiving help does not demand a working shift
  if (recipient.condition.rested < 15) return 'recipient needs sleep';
  if (recipient.condition.fed < 18) return 'recipient needs food';
  const stamp = state.day * 4 + state.watch - 1;
  if (body(state, intent.actor).lastInteractionWatch === stamp) return 'actor has already committed this watch';
  if (recipient.lastInteractionWatch === stamp) return 'recipient has already committed this watch';
  if (state.axes.get(`${intent.target}${intent.actor}`)!.resentment >= 70) return 'recipient declines contact';
  return null;
}

function shareFact(state: WorldState, intent: Intent): string | undefined {
  const from = body(state, intent.actor), to = body(state, intent.target!);
  const id = intent.fact ?? (intent.verb === 'teach' ? from.knownFacts.find((fact) => !FACTS[fact.id]!.private
    && !to.knownFacts.some((known) => known.id === fact.id))?.id : undefined);
  if (id && !to.knownFacts.some((fact) => fact.id === id)) {
    to.knownFacts.push({ id, learnedDay: state.day, source: intent.actor });
    return id;
  }
  return undefined;
}

/** How a conversation moves the six axes. Warm verbs move affection and trust,
 *  hard ones move resentment, and every one of them moves `accompanied`, because
 *  even an argument is company. */
function social(
  state: WorldState, intent: Intent,
  moves: Array<[Parameters<typeof nudge>[3], number, number]>,
  text: (a: string, b: string) => string,
  kind: Happening['kind'] = 'meeting',
): Omit<Happening, 'day' | 'watch' | 'minute'> {
  const { actor } = intent;
  const target = intent.target!;
  // A willing visit is resolved before either person's next visual presence.
  arrive(state, actor, body(state, target).room);
  if (!['give', 'lend', 'repay'].includes(intent.verb)) {
    body(state, target).lastInteractionWatch = state.day * 4 + state.watch - 1;
    body(state, actor).lastInteractionWatch = state.day * 4 + state.watch - 1;
  }
  for (const [axis, fwd, bwd] of moves) {
    nudge(state, actor, target, axis, fwd);
    nudge(state, target, actor, axis, bwd);
  }
  // Enough that company actually answers loneliness. At nine it never did, so
  // the need stayed lit for everybody all the time and drowned out every other
  // reason a person might have to do anything.
  condition(body(state, actor), 'accompanied', 24);
  condition(body(state, target), 'accompanied', 24);
  return {
    room: body(state, actor).room,
    who: [actor, target],
    text: text(first(actor), first(target)),
    kind,
  };
}

export const VERBS: Record<VerbName, Verb> = {
  go: {
    name: 'go',
    family: 'body',
    requires: (state, intent) => {
      if (!intent.room) return 'nowhere named';
      const here = body(state, intent.actor).room;
      if (here === intent.room) return 'already there';
      if (intent.room === 'breach') return 'no air, and the suits are logged out';
      return null;
    },
    run: (state, intent) => {
      const b = body(state, intent.actor);
      arrive(state, intent.actor, intent.room!);
      condition(b, 'rested', -0.2);
      return null;
    },
  },

  rest: {
    name: 'rest',
    family: 'body',
    run: (state, intent) => {
      condition(body(state, intent.actor), 'rested', 30);
      condition(body(state, intent.actor), 'safe', 8);
      return null;
    },
  },

  sleep: {
    name: 'sleep',
    family: 'body',
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', 50);
      condition(b, 'well', 2);
      condition(b, 'safe', 1);
      return null;
    },
  },

  eat: {
    name: 'eat',
    family: 'body',
    requires: (state, intent) => (
      body(state, intent.actor).room !== 'common' ? 'nothing to eat here'
        : body(state, intent.actor).cells < 0.5 && body(state, intent.actor).condition.fed >= 28 ? 'not enough charge; emergency rations are reserved for urgent hunger'
          : state.economy.stock.meals < 1 ? 'no prepared meals remain'
          : state.economy.stock.water < 1 ? 'no clean water remains' : null
    ),
    run: (state, intent) => {
      const b = body(state, intent.actor);
      const fee = Math.min(0.5, b.cells);
      b.cells -= fee;
      state.economy.treasury += fee;
      state.economy.stock.meals -= 1;
      state.economy.stock.water -= 1;
      condition(b, 'fed', 46);
      return fee < 0.5 ? { room: b.room, who: [intent.actor], kind: 'need',
        text: `${first(intent.actor)} received an emergency meal and water; ${fee.toFixed(3)} cells paid, the remaining meal fee waived.` } : null;
    },
  },

  drink: {
    name: 'drink',
    family: 'body',
    requires: (state) => state.economy.stock.water >= 1 ? null : 'no clean water remains',
    run: (state, intent) => {
      state.economy.stock.water -= 1;
      condition(body(state, intent.actor), 'fed', 6);
      return null;
    },
  },

  wash: {
    name: 'wash',
    family: 'body',
    requires: (state, intent) => (
      !['well', 'infirmary', 'washroom'].includes(body(state, intent.actor).room) ? 'no washing station here'
        : state.economy.stock.water < 2 ? 'no clean water remains' : null
    ),
    run: (state, intent) => {
      state.economy.stock.water -= 2;
      condition(body(state, intent.actor), 'well', 26);
      condition(body(state, intent.actor), 'safe', 10);
      return null;
    },
  },

  work: {
    name: 'work',
    family: 'work',
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', -5);
      recordWork(state, intent.actor);
      return null;
    },
  },

  dig: {
    name: 'dig',
    family: 'work',
    requires: (state, intent) => (
      body(state, intent.actor).room !== 'face' ? 'nothing to cut here'
        : state.economy.stock.materials + yieldFor(state, 'face', 4) > CAPACITY.materials ? 'material store is full'
          : state.economy.stock.water < 1 ? 'no water for the cutting equipment' : null
    ),
    run: (state, intent) => {
      const b = body(state, intent.actor);
      const amount = yieldFor(state, b.room, 4);
      condition(b, 'rested', mechanized(state, b.room) ? -8 : -10);
      state.economy.stock.water -= 1;
      state.economy.stock.materials += amount;
      recordWork(state, intent.actor, 2);
      return { room: 'face', who: [intent.actor], text: `${first(intent.actor)} recovered ${amount} usable materials at the face${mechanized(state, b.room) ? '' : ' by hand'}; 1 water used.`, kind: 'work' };
    },
  },

  grow: {
    name: 'grow',
    family: 'work',
    requires: (state, intent) => (
      body(state, intent.actor).room !== 'garden' ? 'nothing growing here'
        : state.economy.stock.produce + yieldFor(state, 'garden', 16) > CAPACITY.produce ? 'produce store is full'
          : state.economy.stock.water < 2 ? 'not enough water for the trays' : null
    ),
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', -5);
      state.economy.stock.water -= 2;
      const amount = yieldFor(state, b.room, 16);
      if (!mechanized(state, b.room)) condition(b, 'rested', -3);
      state.economy.stock.produce += amount;
      recordWork(state, intent.actor, 2);
      return { room: b.room, who: [intent.actor], text: `${first(intent.actor)} harvested ${amount} produce${mechanized(state, b.room) ? '' : ' by hand'}; 2 water used.`, kind: 'work' };
    },
  },

  cook: {
    name: 'cook',
    family: 'work',
    requires: (state, intent) => (
      !['common', 'kitchen'].includes(body(state, intent.actor).room) ? 'no burners here'
        : state.economy.stock.meals + yieldFor(state, body(state, intent.actor).room, 8) > CAPACITY.meals ? 'prepared meal store is full'
          : state.economy.stock.produce < 4 ? 'not enough produce to cook'
            : state.economy.stock.water < 1 ? 'no water for cooking' : null
    ),
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', -5);
      state.economy.stock.produce -= 4;
      state.economy.stock.water -= 1;
      const amount = yieldFor(state, b.room, 8);
      if (!mechanized(state, b.room)) condition(b, 'rested', -3);
      state.economy.stock.meals += amount;
      recordWork(state, intent.actor, 2);
      return { room: b.room, who: [intent.actor], text: `${first(intent.actor)} prepared ${amount} meals${mechanized(state, b.room) ? '' : ' without powered burners'} from 4 produce and 1 water.`, kind: 'work' };
    },
  },

  clean: {
    name: 'clean',
    family: 'work',
    requires: (state, intent) => body(state, intent.actor).room === 'well' && state.economy.stock.water + yieldFor(state, 'well', 24) > CAPACITY.water
      ? 'clean-water store is full' : null,
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', -5);
      condition(b, 'well', 2);
      recordWork(state, intent.actor);
      if (b.room === 'well') {
        const amount = yieldFor(state, b.room, 24);
        if (!mechanized(state, b.room)) condition(b, 'rested', -3);
        state.economy.stock.water += amount;
        return { room: b.room, who: [intent.actor], text: `${first(intent.actor)} filtered ${amount} water at the well${mechanized(state, b.room) ? '' : ' by hand'}.`, kind: 'work' };
      }
      return null;
    },
  },

  inspect: {
    name: 'inspect',
    family: 'work',
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', -3);
      recordWork(state, intent.actor);
      return {
        room: b.room,
        who: [intent.actor],
        text: `${ROOM_BY_ID[b.room].name} was walked through and looked over.`,
        kind: 'work',
      };
    },
  },

  repair: {
    name: 'repair',
    family: 'work',
    requires: (state) => state.economy.stock.materials >= 1 ? null : 'no repair materials remain',
    run: (state, intent) => {
      const b = body(state, intent.actor);
      condition(b, 'rested', -6);
      const powered = b.cells >= 2;
      const charge = powered ? 2 : 0;
      b.cells -= charge; state.economy.ledger.burned += charge;
      condition(b, 'safe', powered ? 22 : 12);
      state.economy.stock.materials -= 1;
      state.economy.maintenance = Math.min(100, state.economy.maintenance + (powered ? 8 : 4));
      recordWork(state, intent.actor, 2);
      return {
        room: b.room,
        who: [intent.actor],
        text: `${first(intent.actor)} repaired ${ROOM_BY_ID[b.room].name}; 1 material and ${charge} charge cells used${powered ? '' : '; slower manual repair'}.`,
        kind: 'work',
      };
    },
  },

  charge: {
    name: 'charge',
    family: 'work',
    requires: (state, intent) => (
      body(state, intent.actor).room === 'workshops' ? null : 'no rack here'
    ),
    run: (state, intent) => {
      recordWork(state, intent.actor, 2);
      condition(body(state, intent.actor), 'rested', -4);
      return null;
    },
  },

  give: {
    name: 'give', family: 'commitment',
    requires: (state, intent) => together(state, intent)
      ?? (body(state, intent.actor).cells < 6 ? 'cannot spare 2 cells and keep a reserve'
        : body(state, intent.target!).cells >= 8 ? 'recipient already has a reserve'
          : !acceptsHelp(state, intent.actor, intent.target!) ? 'recipient declines the gift' : null),
    run: (state, intent) => {
      body(state, intent.actor).cells -= 2;
      body(state, intent.target!).cells += 2;
      return social(state, intent, [['trust', 0, 4], ['affection', 1, 3]],
        (a, b) => `${a} gave ${b} 2 charge cells.`);
    },
  },
  lend: {
    name: 'lend', family: 'commitment',
    requires: (state, intent) => together(state, intent)
      ?? (body(state, intent.actor).cells < 8 ? 'cannot lend 4 cells and keep a reserve'
        : body(state, intent.target!).cells >= 6 ? 'recipient does not need a loan'
          : !acceptsHelp(state, intent.actor, intent.target!) ? 'recipient declines the loan'
            : state.axes.get(`${intent.actor}${intent.target}`)!.trust < 30 ? 'not enough trust to lend'
              : outstanding(state, intent.target!).length >= 2 || outstanding(state, intent.target!, intent.actor).length
                ? 'existing obligation takes precedence' : null),
    run: (state, intent) => {
      const sequence = state.economy.nextDebtSequence++;
      const debt = { id: `${state.day}-${state.watch}-${intent.actor}${intent.target}-${sequence}`, lender: intent.actor,
        borrower: intent.target!, principal: 4, remaining: 4, issuedDay: state.day, dueDay: state.day + 5, status: 'open' as const };
      body(state, intent.actor).cells -= 4;
      body(state, intent.target!).cells += 4;
      // Closed agreements remain in the archive and the most recent 50 in state.
      const paid = state.economy.debts.filter((entry) => entry.status === 'paid').slice(-49);
      state.economy.debts = [...state.economy.debts.filter((entry) => entry.status !== 'paid'), ...paid, debt];
      return social(state, intent, [['trust', 0, 2], ['debt', 0, 4]],
        (a, b) => `${a} lent ${b} 4 charge cells, due on day ${debt.dueDay}.`);
    },
  },
  repay: {
    name: 'repay', family: 'commitment',
    requires: (state, intent) => together(state, intent)
      ?? (!outstanding(state, intent.actor, intent.target).length ? 'nothing owed to this person'
        : body(state, intent.actor).cells < Math.min(2, outstanding(state, intent.actor, intent.target)[0]!.remaining)
          ? 'not enough cells to repay' : null),
    run: (state, intent) => {
      const debt = outstanding(state, intent.actor, intent.target)[0]!;
      const amount = Math.min(2, debt.remaining);
      body(state, intent.actor).cells -= amount;
      body(state, intent.target!).cells += amount;
      debt.remaining -= amount;
      if (debt.remaining === 0) debt.status = 'paid';
      return social(state, intent, [['debt', -amount, 0], ['trust', 0, 3], ['resentment', 0, -4]],
        (a, b) => `${a} repaid ${b} ${amount} charge cells; ${debt.remaining} still owed.`);
    },
