export const VERB_NAMES = CATALOGUE;

/** Try an intent. Refusals are returned rather than thrown, because a refused
 *  intent is information: somebody wanted something and the world said no, and
 *  that is exactly the kind of thing that should cost them a thought later. */
export function attempt(state: WorldState, intent: Intent): Outcome {
  const { actor, ...proposal } = intent;
  const decoded = decodeIntentFor(actor, proposal);
  if (!decoded.ok) return { ok: false, refused: decoded.error };
  const verb = VERBS[intent.verb];
  if (intent.fact && (!body(state, actor).knownFacts.some((fact) => fact.id === intent.fact)
    || (intent.verb === 'teach' && FACTS[intent.fact]!.private))) return { ok: false, refused: 'not authorized to share this knowledge' };
  const why = verb.requires?.(state, intent) ?? null;
  if (why) return { ok: false, refused: why };
  const cost = verb.cost ?? 0;
  const b = body(state, intent.actor);
  if (cost > 0 && b.cells < cost) return { ok: false, refused: 'not enough charge' };
  const before = economicAccounts(state);
  b.cells -= cost;
  state.economy.ledger.burned += cost;
  const happening = verb.run(state, intent);
  const transaction = recordEconomicChange(state, before, intent.verb, intent.actor);
  // A shared meal or task gives company without inventing a conversation,
  // changing trust, or using another resident's deliberate decision. Pair only
  // people who actually performed this activity in this room during this watch.
  if (transaction && (verb.family === 'work' || intent.verb === 'eat')) {
    const earlier = state.economy.events.filter((event) => event !== transaction && event.day === state.day && event.watch === state.watch);
    const paired = new Set(earlier.flatMap((event) => event.companions ?? []));
    const partner = !paired.has(intent.actor) && earlier.find((event) => event.action === intent.verb && event.room === b.room
      && event.actor && event.actor !== intent.actor && !paired.has(event.actor))?.actor;
    if (partner) {
      transaction.companions = [intent.actor, partner];
      condition(b, 'accompanied', 10); condition(body(state, partner), 'accompanied', 10);
    }
  }
  if (happening && !['inspect', 'note'].includes(intent.verb)) {
    remember(state, intent.actor, { kind: intent.verb, ...(intent.target ? { other: intent.target } : {}), outcome: happening.text });
    for (const participant of happening.who) if (participant !== intent.actor) remember(state, participant, { kind: intent.verb, other: intent.actor, outcome: happening.text });
  }
  return { ok: true, ...(happening ? { happening } : {}) };
}

/** What the actor can propose from their own resources and knowledge. A target
 * on this list has not consented; their actual response is evaluated at attempt. */
export function canPropose(state: WorldState, intent: Intent): boolean {
  const { actor, ...proposal } = intent;
  if (!decodeIntentFor(actor, proposal).ok) return false;
  if (!intent.target) return !VERBS[intent.verb].requires?.(state, intent);
  if (intent.target === actor) return false;
  const b = body(state, actor), own = state.axes.get(`${actor}${intent.target}`)!;
  switch (intent.verb) {
    case 'give': return b.cells >= 6;
    case 'lend': return b.cells >= 8 && own.trust >= 30;
    case 'repay': return outstanding(state, actor, intent.target).some((debt) => b.cells >= Math.min(2, debt.remaining));
    case 'trade': return b.cells >= 2 && state.economy.stock.materials >= 1;
    case 'confide': return own.trust >= 55;
    case 'flirt': return own.desire >= 20;
    default: return true;
  }
}

// Where to put twenty-five people on a page.
//
// Not a physics simulation: a deterministic layout, run for a fixed number of
// steps from a fixed start, so the graph is the same graph every time it is
// drawn and a returning visitor recognises it. The clusters are seeded around a
// ring because that is the honest shape of the data — five dense groups with four
// bridges — and then a few relaxation passes let the bridges pull them about so
// it does not read as a diagram of five circles.

import { RESIDENTS, type Cluster, type ResidentId } from './residents';
import { edges, pull, type When } from './weave';

export type Node = { id: ResidentId; x: number; y: number };

const CLUSTERS: readonly Cluster[] = ['I', 'II', 'III', 'IV', 'V'];

/** Layout space. Square, so the view can scale it however it likes. */
export const SPACE = 100;

/** Below this, what is between two people is only proximity. */
const FLOOR = 22;

export function layout(when: When = 'now', steps = 220): Node[] {
  const nodes: Node[] = RESIDENTS.map((r) => {
    const ci = CLUSTERS.indexOf(r.cluster);
    const within = RESIDENTS.filter((o) => o.cluster === r.cluster).findIndex((o) => o.id === r.id);
    const ringA = (ci / CLUSTERS.length) * Math.PI * 2 - Math.PI / 2;
    const ringB = (within / 5) * Math.PI * 2;
    return {
      id: r.id,
      x: SPACE / 2 + Math.cos(ringA) * 30 + Math.cos(ringB) * 9,
      y: SPACE / 2 + Math.sin(ringA) * 30 + Math.sin(ringB) * 9,
    };
  });

  const index = new Map(nodes.map((n, i) => [n.id, i]));
  const all = edges(when);
  const back = new Map(all.map((e) => [`${e.from}${e.to}`, e]));
  const links = all
    .filter((e) => e.from < e.to)
    .map((e) => {
      // Two people pull on each other by however much passes between them, in
      // both directions: one-sided debt draws you in as surely as affection.
      const both = (pull(e) + pull(back.get(`${e.to}${e.from}`)!)) / 2;
      // A hundred days of sharing sixteen rooms is not a bond and must not pull
      // like one, or the five groups the data actually has are flattened into an
      // even mesh and the anomaly stops being visible.
      const over = Math.max(0, both - FLOOR);
      return { a: index.get(e.from)!, b: index.get(e.to)!, strength: (over / 60) ** 1.4 };
    })
    .filter((l) => l.strength > 0);

  for (let step = 0; step < steps; step += 1) {
    const cool = 1 - step / steps;
    // Everybody pushes everybody away, so nobody sits on anybody.
    for (let i = 0; i < nodes.length; i += 1) {
      for (let j = i + 1; j < nodes.length; j += 1) {
        const a = nodes[i]!;
        const b = nodes[j]!;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const d2 = Math.max(1.2, dx * dx + dy * dy);
        const f = (95 / d2) * cool;
        const d = Math.sqrt(d2);
        a.x -= (dx / d) * f;
        a.y -= (dy / d) * f;
        b.x += (dx / d) * f;
        b.y += (dy / d) * f;
      }
    }
    // What is between two people pulls them together.
    for (const l of links) {
      const a = nodes[l.a]!;
      const b = nodes[l.b]!;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const d = Math.max(0.6, Math.hypot(dx, dy));
      const f = (d - 12) * 0.09 * l.strength * cool;
      a.x += (dx / d) * f;
      a.y += (dy / d) * f;
      b.x -= (dx / d) * f;
      b.y -= (dy / d) * f;
    }
    // And the page has edges.
    for (const n of nodes) {
      n.x = Math.min(SPACE - 6, Math.max(6, n.x));
      n.y = Math.min(SPACE - 6, Math.max(6, n.y));
    }
  }
  return nodes;
}

// The alphabet the habitat is written in.
//
// One representation of space serves three readers: the engine moves people
// across this grid, the canvas draws it, and it goes into a model's prompt
// verbatim. An agent is handed the map rather than a description of it, so it can
// count the steps to a door instead of guessing at one. Everything here is a pure
// function over an array of strings, and nothing in this file knows which rooms
// exist.
//
// Three character classes, and they never collide. Symbols are terrain and mean
// the same thing everywhere. Lowercase letters and digits are objects, and their
// meaning is local to a room's legend. Uppercase A–Y are people, and they are
// composited on top at render and perception time rather than living in the grid.

export const TERRAIN = {
  '#': { label: 'solid rock or hull plate', walkable: false },
  '.': { label: 'open', walkable: true },
  '=': { label: 'deck plate or dug floor', walkable: true },
  '|': { label: 'partition', walkable: false },
  '+': { label: 'hatch or doorway', walkable: true },
  X: { label: 'sealed — needs a key, a suit or a tool', walkable: false },
  '^': { label: 'climb up', walkable: true },
  v: { label: 'climb down', walkable: true },
  '~': { label: 'water', walkable: false },
  ':': { label: 'grating', walkable: true },
  ',': { label: 'loose spoil', walkable: true },
  '"': { label: 'living growth', walkable: true },
  '*': { label: 'vacuum, not survivable unsuited', walkable: false },
} as const satisfies Record<string, { label: string; walkable: boolean }>;

export type Terrain = keyof typeof TERRAIN;

export type Point = { x: number; y: number };

/** What a room's own legend says about one object glyph. */
export type LegendEntry = {
  name: string;
  /** Whether it blocks the tile it stands on. A table does; a bench does not. */
  solid: boolean;
};

export type RoomLegend = Record<string, LegendEntry>;

export type Placed = { glyph: string; name: string; x: number; y: number };

export function isTerrain(ch: string): ch is Terrain {
  return Object.prototype.hasOwnProperty.call(TERRAIN, ch);
}

export function gridSize(grid: readonly string[]): { w: number; h: number } {
  return { w: grid[0]?.length ?? 0, h: grid.length };
}

/** The character at a point, or null outside the grid. Callers decide what
 *  off-grid means rather than catching an exception. */
export function cellAt(grid: readonly string[], x: number, y: number): string | null {
  const row = grid[y];
  if (row === undefined) return null;
  if (x < 0 || x >= row.length) return null;
  return row[x] ?? null;
}

export function isSolid(
  grid: readonly string[], legend: RoomLegend, x: number, y: number,
): boolean {
  const ch = cellAt(grid, x, y);
  if (ch === null) return true;
  if (isTerrain(ch)) return !TERRAIN[ch].walkable;
  return legend[ch]?.solid ?? false;
}

export function isWalkable(
  grid: readonly string[], legend: RoomLegend, x: number, y: number,
): boolean {
  return cellAt(grid, x, y) !== null && !isSolid(grid, legend, x, y);
}

/** Objects are scanned out of the grid and never kept in a second list, so a grid
 *  and its objects cannot drift apart. Reading order: top to bottom, left to
 *  right. */
export function placedObjects(grid: readonly string[], legend: RoomLegend): Placed[] {
  const out: Placed[] = [];
  grid.forEach((row, y) => {
    [...row].forEach((ch, x) => {
      const entry = legend[ch];
      if (entry) out.push({ glyph: ch, name: entry.name, x, y });
    });
  });
  return out;
}

/** The square of grid a person at `centre` can take in, clipped rather than
 *  padded, so the caller can tell the edge of a room from open floor. */
export function perceptionWindow(
  grid: readonly string[], centre: Point, radius: number,
): string[] {
  const { w, h } = gridSize(grid);
  const y0 = Math.max(0, centre.y - radius);
  const y1 = Math.min(h - 1, centre.y + radius);
  const x0 = Math.max(0, centre.x - radius);
  const x1 = Math.min(w - 1, centre.x + radius);
  const out: string[] = [];
  for (let y = y0; y <= y1; y += 1) out.push((grid[y] ?? '').slice(x0, x1 + 1));
  return out;
}

