  K: { skin: 6, hair: 0, style: 'coils', brow: 0, eyes: 2, mouth: 0, extra: 'none' },
  N: { skin: 4, hair: 0, style: 'tied', brow: 0, eyes: 0, mouth: 0, extra: 'none' },
