  // The last years.
  E: { skin: 0, hair: 6, style: 'bob', brow: 0, eyes: 1, mouth: 0, extra: 'glasses' },
  C: { skin: 0, hair: 7, style: 'crop', brow: 0, eyes: 1, mouth: 0, extra: 'none' },
