export function portraitOf(id: ResidentId): Portrait {
  return PORTRAITS[id];
}

/** Whether a face carries its years. Used for the lines around the eyes, which
 *  the generator would otherwise scatter at random. */
export function isOld(id: ResidentId): boolean {
  return (RESIDENTS.find((r) => r.id === id)?.age ?? 0) >= 58;
}

// Deterministic randomness shared by the world and its observer.

/** A fast, decent 32-bit PRNG. Same seed, same sequence, every time. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A stable 32-bit seed for any string — an id, a caption, a country. */
export function hashString(value: string): number {
  let h = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

/** Smoothly map `value` from one range onto another, clamped at both ends. */
export function remap(value: number, a0: number, a1: number, b0: number, b1: number): number {
  if (a1 === a0) return b0;
  return b0 + (b1 - b0) * clamp((value - a0) / (a1 - a0), 0, 1);
}

/** A cheap 1-D value noise, good enough for a wobble that has to look alive. */
export function wobble(t: number, seed = 1): number {
  return (
    Math.sin(t * 1.13 + seed * 2.7) * 0.55
    + Math.sin(t * 2.37 + seed * 5.1) * 0.3
    + Math.sin(t * 4.91 + seed * 1.3) * 0.15
  );
}

import manifest from './generated/rooms.json';
import type { Point } from './grid';
import type { RoomId } from './rooms';
import { decodeBitmapRow } from './bitmap-codec';

export type RoomObject = {
  id: string; bounds: [number, number, number, number]; baseY: number;
  mask: readonly string[]; footprintMask?: readonly string[];
  source?: { file: string; rect: [number, number, number, number]; mirrored: boolean };
};
export type RoomExit = {
  at: Point; arrival: Point; outward?: 'north' | 'east' | 'south' | 'west';
  span?: { from: number; to: number }; nativeCenter?: number; width?: number;
};
export type RoomArt = {
  width: number; height: number; cellSize: number; grid: readonly string[];
  entry: Point; exits: readonly RoomExit[]; sealed: boolean;
  footprint?: { width: number; depth: number; behind: number };
  objects?: readonly RoomObject[]; outlineMask?: readonly string[];
  diagnostics?: { pointComponents: number[]; inaccessibleFloorPixels: number };
};
const sourceRooms = manifest.rooms as unknown as Partial<Record<RoomId, RoomArt>>;
export const ROOM_ART = Object.fromEntries(Object.entries(sourceRooms).map(([id, art]) => [id, {
  ...art,
  grid: art.grid.map(decodeBitmapRow),
  ...(art.outlineMask ? { outlineMask: art.outlineMask.map(decodeBitmapRow) } : {}),
  ...(art.objects ? { objects: art.objects.map((object) => ({ ...object, mask: object.mask.map(decodeBitmapRow),
    ...(object.footprintMask ? { footprintMask: object.footprintMask.map(decodeBitmapRow) } : {}),
  })) } : {}),
}])) as Partial<Record<RoomId, RoomArt>>;
export const FEET = { width: 12, depth: 8, behind: 6 } as const;

export function visibleRoom(id: RoomId): RoomId {
  return id === 'longwalk' || id === 'row' || id === 'breach' ? 'common' : id;
}

/** This is also the renderer's integer anchor, including at fractional interpolation times. */
export function roomAnchor(art: RoomArt, point: Point): Point {
  return { x: Math.round((point.x + .5) * art.cellSize), y: Math.round((point.y + .5) * art.cellSize) };
}
export function roomFloor(art: RoomArt, point: Point): boolean {
  return art.grid[point.y]?.[point.x] === '.';
}

type Clearance = { width: number; height: number; free: Uint8Array; components: Int32Array; accessible: Set<number>; spots: Point[] };
const clearances = new WeakMap<RoomArt, Clearance>();
const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]] as const;

function throughPortal(art: RoomArt, left: number, top: number, right: number, bottom: number, width: number, height: number): boolean {
  return art.exits.some((exit) => {
    const side = exit.outward ?? (exit.at.y === 0 ? 'north' : 'south');
    const center = roomAnchor(art, exit.at);
    const horizontal = side === 'north' || side === 'south';
    const from = exit.nativeCenter !== undefined && exit.width !== undefined ? exit.nativeCenter - exit.width / 2
      : exit.span ? exit.span.from * art.cellSize : (horizontal ? center.x : center.y) - 8;
    const to = exit.nativeCenter !== undefined && exit.width !== undefined ? from + exit.width
      : exit.span ? (exit.span.to + 1) * art.cellSize : from + 16;
    if (horizontal && (left < from || right > to || left < 0 || right > width)) return false;
    if (!horizontal && (top < from || bottom > to || top < 0 || bottom > height)) return false;
    return side === 'north' ? top < 0 && bottom <= height
      : side === 'south' ? bottom > height && top >= 0
        : side === 'west' ? left < 0 && right <= width : right > width && left >= 0;
  });
}

function clearance(art: RoomArt): Clearance {
  const cached = clearances.get(art);
  if (cached) return cached;
  const cols = art.grid[0]?.length ?? 0, rows = art.grid.length;
  const width = cols * art.cellSize, height = rows * art.cellSize;
  const stride = width + 1, sums = new Uint32Array(stride * (height + 1));
  for (let y = 0; y < height; y++) {
    let row = 0;
    for (let x = 0; x < width; x++) {
      row += art.grid[Math.floor(y / art.cellSize)]?.[Math.floor(x / art.cellSize)] === '.' ? 1 : 0;
      sums[(y + 1) * stride + x + 1] = sums[y * stride + x + 1]! + row;
    }
  }
  const footprint = art.footprint ?? FEET;
  const free = new Uint8Array(cols * rows), components = new Int32Array(cols * rows).fill(-1);
  for (let y = 0; y < rows; y++) for (let x = 0; x < cols; x++) {
    const at = roomAnchor(art, { x, y });
    const left = at.x - footprint.width / 2, top = at.y - footprint.behind;
    const right = left + footprint.width, bottom = top + footprint.depth;
    if ((left < 0 || top < 0 || right > width || bottom > height) && !throughPortal(art, left, top, right, bottom, width, height)) continue;
    const l = Math.max(0, left), t = Math.max(0, top), r = Math.min(width, right), b = Math.min(height, bottom);
    if (l >= r || t >= b) continue;
    const covered = sums[b * stride + r]! - sums[t * stride + r]! - sums[b * stride + l]! + sums[t * stride + l]!;
    if (covered === (r - l) * (b - t)) free[y * cols + x] = 1;
  }
  let component = 0;
  for (let index = 0; index < free.length; index++) {
    if (!free[index] || components[index] !== -1) continue;
    const queue = [index]; components[index] = component;
    for (let head = 0; head < queue.length; head++) {
      const current = queue[head]!, x = current % cols, y = Math.floor(current / cols);
      for (const [dx, dy] of directions) {
        const nx = x + dx, ny = y + dy, next = ny * cols + nx;
        if (nx < 0 || nx >= cols || ny < 0 || ny >= rows || !free[next] || components[next] !== -1) continue;
        components[next] = component; queue.push(next);
      }
    }
    component++;
  }
  const accessible = new Set<number>();
  for (const entry of art.exits.length ? art.exits.map((exit) => exit.arrival) : [art.entry]) {
    const index = entry.y * cols + entry.x;
    if (free[index]) accessible.add(components[index]!);
  }
  const spots: Point[] = [];
  if (!art.sealed) for (let index = 0; index < free.length; index++) {
    if (free[index] && accessible.has(components[index]!)) spots.push({ x: index % cols, y: Math.floor(index / cols) });
  }
  const result = { width: cols, height: rows, free, components, accessible, spots };
  clearances.set(art, result); return result;
}

/** All 96 native footprint pixels must be floor; a cell centre is insufficient. */
export function standingFloor(art: RoomArt, point: Point): boolean {
  const mask = clearance(art);
  return Number.isInteger(point.x) && Number.isInteger(point.y) && point.x >= 0 && point.y >= 0
    && point.x < mask.width && point.y < mask.height && mask.free[point.y * mask.width + point.x] === 1;
}
export function roomAccessible(art: RoomArt, point: Point): boolean {
  const mask = clearance(art);
  return standingFloor(art, point) && mask.accessible.has(mask.components[point.y * mask.width + point.x]!);
}
export function roomComponent(art: RoomArt, point: Point): number {
  const mask = clearance(art);
  return standingFloor(art, point) ? mask.components[point.y * mask.width + point.x]! : -1;
}

export function roomPath(art: RoomArt, from: Point, to: Point, available?: (point: Point) => boolean): Point[] {
  const mask = clearance(art);
  if (!standingFloor(art, from) || !standingFloor(art, to) || roomComponent(art, from) !== roomComponent(art, to)) return [];
  const start = from.y * mask.width + from.x, goal = to.y * mask.width + to.x;
  const previous = new Int32Array(mask.free.length).fill(-2); previous[start] = -1;
  const pending = [start];
  for (let head = 0; head < pending.length; head++) {
    const at = pending[head]!;
    if (at === goal) {
      const route: Point[] = [];
      for (let index = at; index !== -1; index = previous[index]!) route.push({ x: index % mask.width, y: Math.floor(index / mask.width) });
      return route.reverse();
    }
    const x = at % mask.width, y = Math.floor(at / mask.width);
    for (const [dx, dy] of directions) {
      const nx = x + dx, ny = y + dy, next = ny * mask.width + nx;
      if (nx < 0 || nx >= mask.width || ny < 0 || ny >= mask.height || !mask.free[next] || previous[next] !== -2) continue;
      if (available && !available({ x: nx, y: ny })) continue;
      previous[next] = at; pending.push(next);
    }
  }
  return [];
}

/** Isolated but physically clear floor remains in grid; only arrivals exclude it. */
export function roomStandingSpots(art: RoomArt): Point[] { return clearance(art).spots; }
export function roomNavigationDiagnostics(art: RoomArt) {
  const mask = clearance(art); const counts = new Map<number, number>();
  for (let i = 0; i < mask.free.length; i++) if (mask.free[i]) counts.set(mask.components[i]!, (counts.get(mask.components[i]!) ?? 0) + 1);
  return { components: [...counts].map(([id, positions]) => ({ id, positions, accessible: mask.accessible.has(id) })), accessiblePositions: mask.spots.length };
}
export function roomImage(id: RoomId): string { return `${import.meta.env.BASE_URL}habitat/rooms/${visibleRoom(id)}.png`; }

import type { Point } from './grid';
import type { ResidentId } from './residents';
import { FEET, roomAccessible, roomComponent, roomPath, roomStandingSpots, standingFloor, type RoomArt } from './room-art';

export type Walker = {
  id: ResidentId; at: Point; route: Point[]; next: Point | null;
  waitUntil: number; movedAt: number; step: number;
  duration?: number; goal?: Point;
};
export type RoomOccupancy = { walkers: Walker[]; waiting: ResidentId[] };
/** Four native pixels per step, independently of navigation resolution. */
export const STEP_MS = 190;
export const feetOverlap = (a: Point, b: Point, cellSize = 1): boolean => Math.abs(a.x - b.x) * cellSize < FEET.width && Math.abs(a.y - b.y) * cellSize < FEET.depth;
export const walkerStandingFloor = standingFloor;
export const walkerStandingSpots = roomStandingSpots;

/** Reserve the swept footprint, not merely the two endpoint centres. */
function reservationsOverlap(a: Point, aNext: Point | null, b: Point, bNext: Point | null, cellSize: number): boolean {
  const an = aNext ?? a, bn = bNext ?? b;
  return Math.min(a.x, an.x) * cellSize < Math.max(b.x, bn.x) * cellSize + FEET.width
    && Math.min(b.x, bn.x) * cellSize < Math.max(a.x, an.x) * cellSize + FEET.width
    && Math.min(a.y, an.y) * cellSize < Math.max(b.y, bn.y) * cellSize + FEET.depth
    && Math.min(b.y, bn.y) * cellSize < Math.max(a.y, an.y) * cellSize + FEET.depth;
}
function clearSegment(art: RoomArt, from: Point, to: Point): boolean {
  if (from.x !== to.x && from.y !== to.y) return false;
  const distance = Math.abs(to.x - from.x) + Math.abs(to.y - from.y);
  if (!distance || distance * art.cellSize > 4) return false;
  const dx = Math.sign(to.x - from.x), dy = Math.sign(to.y - from.y);
  for (let n = 1; n <= distance; n++) if (!standingFloor(art, { x: from.x + dx * n, y: from.y + dy * n })) return false;
  return true;
}

/** Access is proved before placement. Isolated clear floor remains diagnosed, never relabelled as wall. */
export function reconcileWalkers(
  occupancy: RoomOccupancy, present: readonly ResidentId[], art: RoomArt,
  spots: readonly Point[], now: number, seed = 0,
): RoomOccupancy {
  const wanted = new Set(present), placed = new Set<ResidentId>();
  const walkers: Walker[] = [];
  for (const walker of occupancy.walkers) {
    if (!wanted.has(walker.id) || placed.has(walker.id) || !roomAccessible(art, walker.at)) continue;
    if (walker.next && !clearSegment(art, walker.at, walker.next)) continue;
    if (walkers.some((other) => reservationsOverlap(walker.at, walker.next, other.at, other.next, art.cellSize))) continue;
    walkers.push(walker); placed.add(walker.id);
  }
  const waiting: ResidentId[] = [];
  for (const id of new Set([...occupancy.waiting, ...present])) {
    if (!wanted.has(id) || placed.has(id)) continue;
    const ordinal = id.charCodeAt(0) - 65;
    const start = spots.length ? (ordinal * 73 + seed * 19) % spots.length : 0;
    let at: Point | undefined;
    for (let offset = 0; offset < spots.length; offset++) {
      const candidate = spots[(start + offset) % spots.length]!;
      if (roomAccessible(art, candidate) && !walkers.some((other) => reservationsOverlap(candidate, null, other.at, other.next, art.cellSize))) { at = candidate; break; }
    }
    if (!at) { waiting.push(id); continue; }
    walkers.push({ id, at, route: [], next: null, waitUntil: now + 500 + ordinal % 7 * 150, movedAt: now, step: 0 });
    placed.add(id);
  }
  return { walkers, waiting };
}

function availableTo(walker: Walker, walkers: Walker[], art: RoomArt, target: Point): boolean {
  return !walkers.some((other) => other !== walker && reservationsOverlap(target, null, other.at, other.next, art.cellSize));
}
/** Small straight groups preserve 21px/s movement on a 1px graph. Turns are never cut. */
function nextSegment(walker: Walker, art: RoomArt): { at: Point; count: number } | null {
  const first = walker.route[0]; if (!first) return null;
  const dx = Math.sign(first.x - walker.at.x), dy = Math.sign(first.y - walker.at.y);
  let at = first, count = 1;
  if (!clearSegment(art, walker.at, first)) return null;
  for (let i = 1; i < walker.route.length && (i + 1) * art.cellSize <= 4; i++) {
    const point = walker.route[i]!;
    if (point.x !== first.x + dx * i || point.y !== first.y + dy * i || !standingFloor(art, point)) break;
    at = point; count++;
  }
  return { at, count };
}

export function advanceWalkers(walkers: Walker[], art: RoomArt, spots: Point[], now: number): void {
  // Complete every in-flight reservation before planning this frame's next segments.
  for (const walker of walkers) {
    if (walker.next && now - walker.movedAt >= (walker.duration ?? STEP_MS)) {
      walker.at = walker.next; walker.next = null;
      if (!walker.route.length) walker.waitUntil = now + 1200 + (walker.id.charCodeAt(0) - 65) % 7 * 230;
    }
  }
  for (const walker of walkers) {
    if (walker.next) continue;
    const ordinal = walker.id.charCodeAt(0) - 65;
    if (!walker.route.length && now >= walker.waitUntil) {
      const component = roomComponent(art, walker.at);
      for (let attempt = 0; attempt < 12; attempt++) {
        const destination = spots[(ordinal * 47 + walker.step * 83 + attempt * 131) % spots.length];
        if (!destination || roomComponent(art, destination) !== component || !availableTo(walker, walkers, art, destination)) continue;
        const path = roomPath(art, walker.at, destination);
        if (path.length > 1) { walker.route = path.slice(1); walker.goal = destination; break; }
      }
      walker.step++; walker.waitUntil = now + 750 + ordinal % 5 * 130;
    }
    let segment = nextSegment(walker, art);
    if (!segment) { walker.route = []; continue; }
    let occupied = walkers.some((other) => other !== walker && reservationsOverlap(walker.at, segment!.at, other.at, other.next, art.cellSize));
    if (occupied && walker.goal) {
      // A person in the corridor can be walked around; an occupied first step is not a wall.
      walker.route = roomPath(art, walker.at, walker.goal, (point) => availableTo(walker, walkers, art, point)).slice(1);
      segment = nextSegment(walker, art);
      occupied = !segment || walkers.some((other) => other !== walker && reservationsOverlap(walker.at, segment!.at, other.at, other.next, art.cellSize));
    }
    if (occupied || !segment) {
      walker.route = []; walker.waitUntil = now + 320 + ordinal % 3 * 70;
    } else {
      walker.next = segment.at; walker.route.splice(0, segment.count); walker.movedAt = now;
      walker.duration = STEP_MS * (Math.abs(segment.at.x - walker.at.x) + Math.abs(segment.at.y - walker.at.y)) * art.cellSize / 4;
    }
  }
}

export function walkerPosition(walker: Walker, now: number): Point {
  const amount = walker.next ? Math.min(1, Math.max(0, (now - walker.movedAt) / (walker.duration ?? STEP_MS))) : 0;
  return { x: walker.at.x + (walker.next ? (walker.next.x - walker.at.x) * amount : 0), y: walker.at.y + (walker.next ? (walker.next.y - walker.at.y) * amount : 0) };
}

// Where everything sits when you look at the whole rock at once.
//
// This is the composition of the hero image, and it is laid out in *tiles* — the
// same tiles the room grids are drawn on — so the map and the room interiors are
// the same world at two magnifications rather than two drawings that have to be
// kept in agreement.
//
// Rooms are packed, not scattered. A cutaway of somewhere people live looks like
// a doll's house: chambers sharing walls and floors, with short passages cut
// between them and solid rock in the gaps. Floating boxes joined by hairlines is
// a diagram, and a diagram is what this deliberately stopped being.
//
// The ship goes in bow-first at twenty-two degrees. Its nose is still out in
// vacuum; everything aft of the dock is buried.

import { gridSize } from './grid';
import { mulberry32 } from './random';
import { ROOMS, ROOM_BY_ID, type RoomId, type Side } from './rooms';

/** The frame, in tiles. Everything is composed inside this.
 *
 *  It shrank by more than half when the rooms did. A room is now the size of the
 *  render it is traced from — five to nine tiles — so the whole habitat fits in a
 *  frame a quarter the area of the one the ladder-stacked version needed, and the
 *  rock still runs off three sides. */
export const FRAME = { w: 92, h: 98 } as const;

/** Degrees off vertical. The whole hull is strung along this. */
export const TILT = 22;

const TAN_TILT = Math.tan((TILT * Math.PI) / 180);

/** Top-left corner of the bow, in tiles. Out in vacuum: everything from the Dock
 *  down is under rock. */
const BOW = { x: 7, y: 2 } as const;

/** Tiles of clear deck between one hull room and the next.
 *
 *  This is the Long Walk, and it is why the hull is a chain of rooms rather than
 *  a stack of them: the corridor is a place with its own width, not a line drawn
 *  between two boxes. */
export const WALK = 2;

/** The hull, bow to stern along the Long Walk. Each room hangs off the axis at
 *  the tilt, so the seven of them read as one vessel driven into rock.
 *
 *  The Long Walk is one of them, and it is the longest: five cabins open off it,
 *  and they are placed against it rather than along the chain. The Breach is on
 *  neither — it is the tear in the flank, reached through a hatch that is sealed. */
export const HULL_WALK: readonly RoomId[] = [
  'bridge', 'dock', 'longwalk', 'hold', 'infirmary',
];

/** The five cabins, against the Long Walk: three to port, two to starboard, and
 *  the free strip opposite the first is where the Throat leaves for the rock.
 *  `at` is the row of the walk each one opens onto, which is also the offset of
 *  its top corner — so a cabin's door and the walk's door are the same doorway by
 *  construction rather than by counting. */
const CABIN_BLOCK: readonly { id: RoomId; side: 'w' | 'e'; at: number }[] = [
  { id: 'cabin1', side: 'w', at: 0 },
  { id: 'cabin2', side: 'w', at: 8 },
  { id: 'cabin3', side: 'w', at: 16 },
  { id: 'cabin4', side: 'e', at: 8 },
  { id: 'cabin5', side: 'e', at: 16 },
