import { RESIDENTS, type ResidentId } from './residents';
import { CONDITIONS, type Condition, type WorldState } from './engine/state';
import { CAPACITY, RESOURCES, type Debt, type Economy } from './engine/economy';

export type SocietySnapshot = {
  startedOnDay: number;
  stock: Economy['stock'];
  treasury: number;
  maintenance: number;
  balances: Array<{ id: ResidentId; cells: number; workCreditsToday: number; conditions: Record<Condition, number> }>;
  debts: Debt[];
  ledger: Economy['ledger'];
};

/** One projection of the same committed world as the room and relationship view. */
export function worldSociety(state: WorldState): SocietySnapshot {
  return {
    startedOnDay: state.economy.startedOnDay,
    stock: { ...state.economy.stock }, treasury: state.economy.treasury,
    maintenance: state.economy.maintenance,
    balances: RESIDENTS.map(({ id }) => ({
      id, cells: state.bodies[id].cells, workCreditsToday: state.economy.workCredits[id],
      conditions: { ...state.bodies[id].condition },
    })),
    debts: state.economy.debts.map((debt) => ({ ...debt })), ledger: { ...state.economy.ledger },
  };
}

const object = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null && !Array.isArray(value);
const nonnegative = (value: unknown): value is number => typeof value === 'number' && Number.isFinite(value) && value >= 0;
const knownId = (value: unknown): value is ResidentId => typeof value === 'string' && RESIDENTS.some((resident) => resident.id === value);

export function isSocietySnapshot(value: unknown): value is SocietySnapshot {
  if (!object(value) || !Number.isInteger(value.startedOnDay) || (value.startedOnDay as number) < 100
    || !object(value.stock) || !RESOURCES.every((key) => nonnegative(value.stock && (value.stock as Record<string, unknown>)[key])
      && ((value.stock as Record<string, number>)[key] ?? Infinity) <= CAPACITY[key])
    || !nonnegative(value.treasury) || !nonnegative(value.maintenance) || value.maintenance > 100
    || !Array.isArray(value.balances) || value.balances.length !== RESIDENTS.length
    || !Array.isArray(value.debts) || !object(value.ledger)
    || !['initialCells', 'minted', 'burned', 'leaked'].every((key) => nonnegative((value.ledger as Record<string, unknown>)[key]))) return false;
  const seen = new Set<string>();
  for (const balance of value.balances) {
    if (!object(balance) || !knownId(balance.id) || seen.has(balance.id)
      || !nonnegative(balance.cells) || !nonnegative(balance.workCreditsToday) || !object(balance.conditions)
      || !CONDITIONS.every((key) => nonnegative((balance.conditions as Record<string, unknown>)[key])
        && (balance.conditions as Record<string, number>)[key]! <= 100)) return false;
    seen.add(balance.id);
  }
  const debtIds = new Set<string>();
  for (const debt of value.debts) {
    if (!object(debt) || typeof debt.id !== 'string' || !debt.id || debtIds.has(debt.id)
      || !knownId(debt.lender) || !knownId(debt.borrower) || debt.lender === debt.borrower
      || !nonnegative(debt.principal) || debt.principal === 0 || !nonnegative(debt.remaining)
      || debt.remaining > debt.principal || !Number.isInteger(debt.issuedDay) || !Number.isInteger(debt.dueDay)
      || (debt.dueDay as number) < (debt.issuedDay as number) || !['open', 'paid', 'overdue'].includes(String(debt.status))
      || (debt.status === 'paid') !== (debt.remaining === 0)) return false;
    debtIds.add(debt.id);
  }
  const society = value as SocietySnapshot;
  const money = society.treasury + society.balances.reduce((sum, person) => sum + person.cells, 0);
  const expected = society.ledger.initialCells + society.ledger.minted - society.ledger.burned - society.ledger.leaked;
  return Math.abs(money - expected) < 1e-6 * Math.max(1, money);
}

import { z } from 'zod';
import { nudge } from '../engine/state';
import type { ResidentId } from '../residents';
import { evidence } from './state';
import type { PreparedTurn, SocietyResult, SocietyState } from './types';

const AXES = ['trust', 'affection', 'admiration', 'resentment'] as const;
const appraisal = z.strictObject({ axis: z.enum(AXES), delta: z.union([z.literal(-1), z.literal(1)]),
  ref: z.string().min(1).max(100), why: z.string().trim().min(1).max(180) });
export type ValidatedAppraisal = z.infer<typeof appraisal> & {
  conversationId: string; target: ResidentId; index: number;
};

/** Only the current, offered incoming message can ground a personal appraisal.
 * A transcript is a claim, not proof that its speaker's assertions are true. */
function receivedTurn(state: SocietyState, turn: PreparedTurn) {
  const c = state.conversations.find((c) => c.id === turn.conversation?.id);
  if (!c || c.status !== 'open' || c.expiresAtMs <= turn.preparedAtMs || c.nextSpeaker !== turn.actor
    || c.revision !== turn.conversation?.revision || c.turns.length !== turn.conversation.turn) return null;
  const member = c.participants.indexOf(turn.actor), received = c.turns.at(-1);
  if (member < 0 || !received || received.speaker === turn.actor || !c.participants.includes(received.speaker)
    || !turn.evidenceIds.includes(received.id) || received.atMs > turn.preparedAtMs
    || received.index <= (c.appraisedThrough?.[member] ?? -1)) return null;
  return { c, received };
}

export function appraisalJsonSchema(state: SocietyState, turn: PreparedTurn): Record<string, unknown> | undefined {
  const available = receivedTurn(state, turn);
  if (!available) return undefined;
  return { type: 'object', additionalProperties: false, required: ['axis', 'delta', 'ref', 'why'],
    properties: { axis: { enum: AXES }, delta: { type: 'integer', enum: [-1, 1] },
      ref: { const: available.received.id }, why: { type: 'string', minLength: 1, maxLength: 180 } },
    description: 'Optional private interpretation of the latest received message. Change only one of your own feelings toward its speaker by one point; omission changes none. Speech is not proof or consent.' };
}

export function validateAppraisal(state: SocietyState, turn: PreparedTurn, raw: unknown):
  { ok: true; value: ValidatedAppraisal } | { ok: false; code: string } {
  const parsed = appraisal.safeParse(raw);
  if (!parsed.success) return { ok: false, code: 'invalid_appraisal' };
  const available = receivedTurn(state, turn);
  if (!available || parsed.data.ref !== available.received.id) return { ok: false, code: 'unavailable_appraisal' };
  return { ok: true, value: { ...parsed.data, conversationId: available.c.id,
    target: available.received.speaker, index: available.received.index } };
}

/** Mutates only the successful base operation's private draft. Call validation
 * before applying the base response: its reply may close the conversation.
 * Failed/replayed operations and repeated helper calls have no appraisal effect. */
export function applyAppraisal(result: SocietyResult, turn: PreparedTurn, value: ValidatedAppraisal, nowMs: number): SocietyResult {
  if (!result.ok || result.code !== 'applied' || result.state.minds[turn.actor]?.lastAppliedSequence !== turn.sequence
    || !Number.isSafeInteger(nowMs) || nowMs < turn.preparedAtMs || nowMs >= turn.expiresAtMs) return result;
  const c = result.state.conversations.find((c) => c.id === value.conversationId), member = c?.participants.indexOf(turn.actor) ?? -1;
  const received = c?.turns[value.index];
  if (!c || member < 0 || c.id !== turn.conversation?.id || value.index !== turn.conversation.turn - 1
    || !received || received.id !== value.ref || received.speaker !== value.target || value.target === turn.actor
    || !c.participants.includes(value.target) || !turn.evidenceIds.includes(value.ref)
    || value.index <= (c.appraisedThrough?.[member] ?? -1)) return result;
  // Watermarks belong to the retained conversation, not its evictable memories.
  // Consume even a clamped change so the same message cannot be tried again.
  c.appraisedThrough ??= [-1, -1];
  c.appraisedThrough[member] = value.index;
  nudge(result.world, turn.actor, value.target, value.axis, value.delta);
  evidence(result.state, turn.actor, result.world, nowMs, 'interpretation',
    `My ${value.axis} toward ${value.target}: ${value.delta > 0 ? '+' : ''}${value.delta} requested after ${value.ref}. ${value.why}`,
    [value.ref], turn.actor, 4);
  return result;
}

import { z } from 'zod';
import type { WorldState } from '../engine/state';
import type { VerbName } from '../engine/verbs';
import { ROOMS } from '../rooms';
import { applySocietyChoice, decodeSocietyChoice, societyChoiceJsonSchema, type SocietyChoiceDecode } from './choice';
import { appraisalJsonSchema, applyAppraisal, validateAppraisal, type ValidatedAppraisal } from './appraisal';
import type { PreparedTurn, SocietyResult, SocietyState } from './types';

/** Protocol 3 names describe existing effects. This is a model-facing boundary,
 * not new engine verbs or a migration of saved intentions and agreements. */
export const CAPABILITY_ALIASES = {
  accrue_labor_credit: 'work',
  walk_room_and_log_visit: 'inspect',
  accrue_two_labor_credits: 'charge',
  log_stock_register: 'note',
  filter_water: 'clean',
  clean_space: 'clean',
} as const satisfies Record<string, VerbName>;
const UNCHANGED_CAPABILITIES = ['go', 'rest', 'sleep', 'eat', 'drink', 'wash', 'dig', 'grow', 'cook', 'repair', 'repay'] as const;
export type CapabilityName = keyof typeof CAPABILITY_ALIASES | typeof UNCHANGED_CAPABILITIES[number];
type Shape = Record<string, unknown>;
const object = (value: unknown): value is Shape => value !== null && typeof value === 'object' && !Array.isArray(value);

/** `null` means there is no corresponding offered capability. Cleaning needs a
 * known destination: callers must not guess that a legacy at:null is outside
 * the Well. `observe` remains valid in the engine and version 2 only. */
export function capabilityForVerb(verb: string, room?: string | null): CapabilityName | null {
  switch (verb) {
    case 'work': return 'accrue_labor_credit';
    case 'inspect': return 'walk_room_and_log_visit';
    case 'charge': return 'accrue_two_labor_credits';
    case 'note': return 'log_stock_register';
    case 'clean': return ROOMS.some(({ id }) => id === room) ? room === 'well' ? 'filter_water' : 'clean_space' : null;
    default: return (UNCHANGED_CAPABILITIES as readonly string[]).includes(verb) ? verb as CapabilityName : null;
  }
}

/** Non-mutating projection for a step, example or work agreement's terms. For
 * stored steps, pass the canonical intent together with its `at`. Resolve the
 * destination before calling when a legacy step inherits its room. This names
 * the effect; it does not assert current resources, consent or availability. */
export function toCapabilityAction<T extends { verb: string; at?: string | null; room?: string }>(action: T,
  fallbackRoom?: string): (Omit<T, 'verb'> & { verb: CapabilityName }) | null {
  const verb = capabilityForVerb(action.verb, action.at ?? action.room ?? fallbackRoom);
  return verb ? { ...structuredClone(action), verb } : null;
}

function canonicalVerb(capability: string): string {
  return Object.hasOwn(CAPABILITY_ALIASES, capability)
    ? CAPABILITY_ALIASES[capability as keyof typeof CAPABILITY_ALIASES] : capability;
}

function stringChoices(schema: unknown, definitions: Shape): string[] {
  if (!object(schema)) return [];
  if (typeof schema.const === 'string') return [schema.const];
  if (Array.isArray(schema.enum)) return schema.enum.filter((value): value is string => typeof value === 'string');
  if (typeof schema.$ref === 'string' && schema.$ref.startsWith('#/$defs/'))
    return stringChoices(definitions[schema.$ref.slice('#/$defs/'.length)], definitions);
  return [];
}

/** Keep every v2 recipient, amount, evidence, facility and dialogue restriction.
 * Only schemas for actual verb-bearing objects are rewritten; text/goal strings
 * and the negotiation's kind/role "work" are not actions and remain untouched. */
export function capabilityChoiceJsonSchema(state: SocietyState, world: WorldState, turn: PreparedTurn): Shape {
  const schema = structuredClone(societyChoiceJsonSchema(state, world, turn));
  const appraisal = appraisalJsonSchema(state, turn);
  if (appraisal && object(schema.properties)) schema.properties.appraisal = appraisal;
  const definitions = object(schema.$defs) ? schema.$defs : {};
  let needsNonWellRoom = false;
  const rewrite = (value: unknown): unknown => {
    if (Array.isArray(value)) return value.map(rewrite);
    if (!object(value)) return value;
    if (object(value.properties) && object(value.properties.verb)) {
      const properties = value.properties, verbs = stringChoices(properties.verb, definitions);
      const names = verbs.filter(verb => verb !== 'clean').flatMap(verb => {
        const capability = capabilityForVerb(verb);
        return capability ? [capability] : [];
      });
      const variants: Shape[] = [];
      if (names.length) variants.push({ ...value, properties: { ...properties,
        verb: names.length === 1 ? { const: names[0] } : { enum: names } } });
      if (verbs.includes('clean')) {
        const key = Object.hasOwn(properties, 'at') ? 'at' : 'room';
        const rooms = stringChoices(properties[key], definitions);
        if (rooms.includes('well')) variants.push({ ...value, properties: { ...properties,
          verb: { const: 'filter_water' }, [key]: { const: 'well' } } });
        const others = rooms.filter(room => room !== 'well');
        if (others.length) {
          const allOtherRooms = stringChoices(definitions.room, definitions).filter(room => room !== 'well');
          const shared = JSON.stringify(others) === JSON.stringify(allOtherRooms);
          if (shared) needsNonWellRoom = true;
          variants.push({ ...value, properties: { ...properties, verb: { const: 'clean_space' },
            [key]: shared ? { $ref: '#/$defs/nonWellRoom' } : { enum: others } } });
        }
      }
      return variants.length === 1 ? variants[0] : { anyOf: variants };
    }
    return Object.fromEntries(Object.entries(value).map(([key, child]) => {
      const translated = rewrite(child);
      // Flatten only wrappers introduced above, preserving metadata-bearing
      // branches. Compact, disjoint alternatives work in provider grammars too.
      return [key, key === 'anyOf' && Array.isArray(translated) ? translated.flatMap(branch =>
        object(branch) && Object.keys(branch).length === 1 && Array.isArray(branch.anyOf) ? branch.anyOf : [branch]) : translated];
    }));
  };
  const translated = rewrite(schema) as Shape;
  if (needsNonWellRoom) translated.$defs = { ...definitions,
    nonWellRoom: { enum: stringChoices(definitions.room, definitions).filter(room => room !== 'well') } };
  return translated;
}

function translateValidatedChoice(state: SocietyState, world: WorldState, turn: PreparedTurn, raw: unknown):
  { ok: true; value: Shape; appraisal?: ValidatedAppraisal } | { ok: false; code: string } {
  if (!state.minds[turn.actor]) return { ok: false, code: 'invalid_job' };
  // Validate the entire external grammar before translation. Old aliases,
  // forbidden locations, fabricated evidence and extra fields cannot be washed
  // into valid canonical data by the adapter.
  if (!z.fromJSONSchema(capabilityChoiceJsonSchema(state, world, turn)).safeParse(raw).success)
    return { ok: false, code: 'unavailable_capability_choice' };
  const choice = structuredClone(raw) as Shape;
  let appraisal: ValidatedAppraisal | undefined;
  if (Object.hasOwn(choice, 'appraisal')) {
    const validated = validateAppraisal(state, turn, choice.appraisal);
    if (!validated.ok) return validated;
    appraisal = validated.value;
    delete choice.appraisal;
  }
  if (object(choice.project) && choice.project.mode === 'replace' && Array.isArray(choice.project.steps)) {
    choice.project.steps = choice.project.steps.map((step: Shape) => ({ ...step, verb: canonicalVerb(step.verb as string) }));
  }
  if (object(choice.deal) && choice.deal.kind === 'work') choice.deal.verb = canonicalVerb(choice.deal.verb as string);
  return { ok: true, value: choice, ...(appraisal ? { appraisal } : {}) };
}

export function decodeCapabilityChoice(state: SocietyState, world: WorldState, turn: PreparedTurn, raw: unknown): SocietyChoiceDecode {
  const translated = translateValidatedChoice(state, world, turn, raw);
  return translated.ok ? decodeSocietyChoice(state, world, turn, translated.value) : translated;
}

export function applyCapabilityChoice(state: SocietyState, world: WorldState, turn: PreparedTurn, raw: unknown,
  control: { nowMs: number; generation: number }): SocietyResult {
  // Current grammar may differ after the first application. Preserve version
  // 2's replay/control ordering before looking at a repeated response's shape.
  if (state.minds[turn.actor] && turn.sequence <= state.minds[turn.actor].lastAppliedSequence)
    return applySocietyChoice(state, world, turn, {}, control);
  const translated = translateValidatedChoice(state, world, turn, raw);
  if (!translated.ok) return { ok: false, code: translated.code, state, world };
  const result = applySocietyChoice(state, world, turn, translated.value, control);
  return translated.appraisal ? applyAppraisal(result, turn, translated.appraisal, control.nowMs) : result;
}

import { z } from 'zod';
import { ROOMS } from '../rooms';
import type { WorldState } from '../engine/state';
import { parseTurnResponse, societyTurnJsonSchema } from './schema';
import { minimumWorkDeadline } from './economy';
import { watchNumber } from './state';
import { applySocietyTurn } from './turn';
import { SOCIETY_LIMITS, WORK_VERBS, type PreparedTurn, type SocietyResult, type SocietyState, type TurnResponse } from './types';

export const SOCIETY_OFFER_LIFETIME_WATCHES = 2;
const cells = z.number().min(0).max(1000)
  .refine((value) => Math.abs(value * 100 - Math.round(value * 100)) < 1e-8, 'cells use at most two decimal places');
const positiveCells = cells.refine((value) => value > 0, 'a transfer or loan must be positive');
const room = z.enum(ROOMS.filter((r) => r.id !== 'breach').map((r) => r.id));
const dealSchema = z.discriminatedUnion('kind', [
  z.strictObject({ kind: z.literal('transfer'), direction: z.enum(['give', 'ask']), cells: positiveCells }),
  z.strictObject({ kind: z.literal('loan'), direction: z.enum(['lend', 'borrow']), cells: positiveCells,
    dueInDays: z.number().int().min(1).max(30) }),
  z.strictObject({ kind: z.literal('work'), role: z.enum(['work', 'hire']), cells,
    verb: z.enum(WORK_VERBS), room, units: z.number().int().min(1).max(4), slackWatches: z.number().int().min(0).max(11) }),
  z.strictObject({ kind: z.literal('accept'), offerId: z.string().min(1).max(100) }),
  z.strictObject({ kind: z.literal('reject'), offerId: z.string().min(1).max(100) }),
]);
const choiceSchema = z.strictObject({ project: z.unknown().optional(), reflection: z.unknown().optional(),
  message: z.unknown().optional(), deal: dealSchema.optional() });
export type SocietyDealChoice = z.infer<typeof dealSchema>;
export type SocietyChoice = Pick<TurnResponse, 'project' | 'reflection' | 'message'> & { deal?: SocietyDealChoice };
export type SocietyChoiceDecode = { ok: true; value: TurnResponse } | { ok: false; code: string };
type Shape = Record<string, unknown>;

/** External grammar only. Persisted offers and agreements continue using the
 * canonical TurnResponse contract, so old lives need no conversion or reset. */
export function societyChoiceJsonSchema(state: SocietyState, world: WorldState, turn: PreparedTurn): Shape {
  const canonical = societyTurnJsonSchema(state, world, turn);
  const properties = { ...canonical.properties as Record<string, Shape> };
  delete properties.offer; delete properties.respond;
  const active = state.conversations.find((c) => c.id === turn.conversation?.id && c.status === 'open'
    && c.expiresAtMs > turn.preparedAtMs && c.participants.includes(turn.actor) && c.nextSpeaker === turn.actor);
  const obj = (fields: Record<string, Shape>): Shape => ({ type: 'object', properties: fields,
    required: Object.keys(fields), additionalProperties: false });
  const integer = (minimum: number, maximum: number): Shape => ({ type: 'integer', minimum, maximum });
  const amount = (minimum: number): Shape => ({ type: 'number', minimum, maximum: 1000, multipleOf: 0.01 });
  const workFields = { kind: { const: 'work' }, role: { enum: ['work', 'hire'] }, cells: amount(0),
    units: integer(1, 4), slackWatches: integer(0, 11) };
  // Facilities are public permanent constraints. Stocks, health and the other
  // party's available funds are deliberately not a proposal-time oracle.
  const work = [
    obj({ ...workFields, verb: { enum: ['work', 'clean', 'inspect', 'repair'] }, room: { $ref: '#/$defs/room' } }),
    ...([['dig', ['face']], ['grow', ['garden']], ['cook', ['common', 'kitchen']], ['charge', ['workshops']]] as const)
      .map(([verb, rooms]) => obj({ ...workFields, verb: { const: verb }, room: { enum: rooms } })),
  ];
  const variants: Shape[] = [];
  if (active && properties.message) {
    if (active.turns.length < SOCIETY_LIMITS.turns - 1) variants.push(
      obj({ kind: { const: 'transfer' }, direction: { enum: ['give', 'ask'] }, cells: amount(0.01) }),
      obj({ kind: { const: 'loan' }, direction: { enum: ['lend', 'borrow'] }, cells: amount(0.01), dueInDays: integer(1, 30) }),
      ...work,
    );
    const incoming = state.offers.filter((o) => o.conversationId === active.id && o.status === 'open'
      && o.counterpart === turn.actor && o.expiresAtWatch > watchNumber(world) && turn.evidenceIds.includes(o.id)).map((o) => o.id);
    if (incoming.length) variants.push(obj({ kind: { enum: ['accept', 'reject'] }, offerId: { enum: incoming } }));
  }
  if (variants.length) properties.deal = { anyOf: variants,
    description: 'Choose one deal. Requires a message to your counterpart with close:false. New offers expire after 2 watches; a proposal does not accept any existing offer.' };
  const firstPurpose = !state.minds[turn.actor].project;
  const required = firstPurpose ? ['project'] : [];
  // The first opportunity is an introduction when someone is available; an
  // active reply must address its speaker. Later private reviews may be silent.
  // Neither requirement exposes a private goal or implies agreement: close:true
  // remains available for a refusal without a deal.
  if (properties.message && (firstPurpose || active)) required.push('message');
  return { ...canonical, properties, ...(required.length ? { required } : {}) };
}

/** Resolve only relative roles and durations. No model-supplied party, price
 * correction, implied consent or rewrite of an existing offer is permitted. */
export function decodeSocietyChoice(state: SocietyState, world: WorldState, turn: PreparedTurn, raw: unknown): SocietyChoiceDecode {
  if (!state.minds[turn.actor]) return { ok: false, code: 'invalid_job' };
  const parsed = choiceSchema.safeParse(raw);
  if (!parsed.success) return { ok: false, code: 'invalid_choice' };
  const { deal, ...common } = parsed.data;
  if (!state.minds[turn.actor]?.project && common.project === undefined) return { ok: false, code: 'initial_project_required' };
  const canonical = parseTurnResponse(common);
  if (!canonical.ok) return canonical;
  if (!z.fromJSONSchema(societyChoiceJsonSchema(state, world, turn)).safeParse(raw).success) {
    return { ok: false, code: 'unavailable_choice' };
  }
  const response = canonical.value;
  if (!deal) return { ok: true, value: response };
  const message = response.message;
  if (!message || message.close !== false) return { ok: false, code: 'deal_requires_open_message' };
  const active = state.conversations.find((c) => c.id === turn.conversation?.id && c.status === 'open'
    && c.expiresAtMs > turn.preparedAtMs && c.nextSpeaker === turn.actor && c.participants.includes(turn.actor));
  const counterpart = active?.participants.find((id) => id !== turn.actor);
  if (!counterpart || message.to !== counterpart) return { ok: false, code: 'unavailable_dialogue_turn' };
  if (deal.kind === 'accept' || deal.kind === 'reject') {
    return { ok: true, value: { ...response, respond: { decision: deal.kind, offerId: deal.offerId } } };
  }
  let terms: NonNullable<TurnResponse['offer']>['terms'];
  if (deal.kind === 'transfer') terms = { kind: 'transfer', cells: deal.cells,
    from: deal.direction === 'give' ? turn.actor : counterpart, to: deal.direction === 'give' ? counterpart : turn.actor };
  else if (deal.kind === 'loan') terms = { kind: 'loan', cells: deal.cells, dueDay: world.day + deal.dueInDays,
    from: deal.direction === 'lend' ? turn.actor : counterpart, to: deal.direction === 'lend' ? counterpart : turn.actor };
  else {
    const worker = deal.role === 'work' ? turn.actor : counterpart;
    // One safety watch beyond the inclusive minimum. Re-evaluated from actual
    // clocks when proposing; acceptance never extends the resulting dueWatch.
    const stamp = watchNumber(world);
    const dueWatch = minimumWorkDeadline(state, world, worker, deal.units) + 1 + deal.slackWatches;
    if (!Number.isSafeInteger(dueWatch) || dueWatch > stamp + 16) return { ok: false, code: 'invalid_work_deadline' };
    terms = { kind: 'work', worker, payer: worker === turn.actor ? counterpart : turn.actor,
      cells: deal.cells, verb: deal.verb, room: deal.room, units: deal.units, dueWatch };
  }
  return { ok: true, value: { ...response, offer: { terms, expiresInWatches: SOCIETY_OFFER_LIFETIME_WATCHES } } };
}

export function applySocietyChoice(state: SocietyState, world: WorldState, turn: PreparedTurn, raw: unknown,
  control: { nowMs: number; generation: number }): SocietyResult {
  // Preserve the canonical replay rule before the now-current grammar changes
  // (e.g. an accepted offer disappears or the recipient's turn changes).
  if (state.minds[turn.actor] && turn.sequence <= state.minds[turn.actor].lastAppliedSequence) {
    return applySocietyTurn(state, world, turn, {}, control);
  }
  const decoded = decodeSocietyChoice(state, world, turn, raw);
  return decoded.ok ? applySocietyTurn(state, world, turn, decoded.value, control)
    : { ok: false, code: decoded.code, state, world };
}

import { economicAccounts, outstanding, recordEconomicChange, remember } from '../engine/economy';
import { nudge, type WorldState } from '../engine/state';
import { VERBS } from '../engine/verbs';
import type { ResidentId } from '../residents';
import { SOCIETY_LIMITS as L, type Agreement, type Offer, type OfferTerms, type SocietyState } from './types';
import { evidence, makeRoom, nextSocietyId, watchNumber } from './state';
import { canSpendCells } from './money';

export function parties(terms: OfferTerms): [ResidentId, ResidentId] {
  return terms.kind === 'work' ? [terms.worker, terms.payer] : [terms.from, terms.to];
}
/** Reservations are promises, not an invented escrow account. Existing physical
 * spending can still use these cells, so payment always rechecks actual funds. */
export function promisedCells(state: SocietyState, payer: ResidentId, except?: string): number {
  return state.agreements.reduce((sum, a) => sum + (a.id !== except && a.terms.kind === 'work'
    && a.terms.payer === payer && ['active', 'payment_due'].includes(a.status) ? a.terms.cells : 0), 0);
}
/** A watch supplies one productive action, including travel through `at`.
 * The due watch is inclusive. A slot already observed cannot be sold again;
 * choosing a separate `go` step still spends its own slot. This is feasibility,
 * not a promise that resources, health or the worker's priorities stay unchanged. */
export function minimumWorkDeadline(state: SocietyState, world: WorldState, worker: ResidentId, units: number): number {
  return Math.max(watchNumber(world), state.minds[worker].lastPhysicalWatch + 1) + units - 1;
}
export function workDeadlineProblem(state: SocietyState, world: WorldState,
  terms: Extract<OfferTerms, { kind: 'work' }>): string | null {
  if (terms.room === 'breach') return 'inaccessible_work_room';
  return terms.dueWatch < minimumWorkDeadline(state, world, terms.worker, terms.units)
    || terms.dueWatch > watchNumber(world) + 16 ? 'invalid_work_deadline' : null;
}
export function termsProblem(state: SocietyState, world: WorldState, terms: OfferTerms): string | null {
  const [a, b] = parties(terms);
  if (a === b) return 'self_agreement';
  if (terms.kind !== 'work') {
    if (terms.cells <= 0) return 'invalid_amount';
    if (!canSpendCells(world.bodies[terms.from].cells, terms.cells, promisedCells(state, terms.from))) return 'insufficient_cells';
    if (terms.kind === 'loan') {
      if (terms.dueDay <= world.day || terms.dueDay > world.day + 30) return 'invalid_loan_due_day';
      if (outstanding(world, terms.to).length >= 2 || outstanding(world, terms.to, terms.from).length) return 'existing_loan_limit';
    }
    return null;
  }
  const deadline = workDeadlineProblem(state, world, terms);
  if (deadline) return deadline;
  if (!canSpendCells(world.bodies[terms.payer].cells, terms.cells, promisedCells(state, terms.payer))) return 'insufficient_cells';
  // Completed labour no longer occupies its worker. An unpaid invoice remains
  // reserved against the payer, without preventing its creditor from working.
  if (state.agreements.some((a) => a.terms.kind === 'work' && a.terms.worker === terms.worker
    && a.status === 'active' && a.progress < a.terms.units)) return 'existing_work_commitment';
  // A work agreement may be made remotely. Its room is a destination, never an
  // assertion that a body has already moved there or performed labour.
  const sample = structuredClone(world);
  sample.bodies[terms.worker].room = terms.room;
  if (VERBS[terms.verb].requires?.(sample, { actor: terms.worker, verb: terms.verb })) return 'work_resources_unavailable';
  return null;
}
function transfer(world: WorldState, from: ResidentId, to: ResidentId, cells: number, label: string): void {
  const before = economicAccounts(world);
  // A tolerated rounding shortfall must not produce a negative account or mint
  // a correction. Debit and credit the same available representable amount.
  const transferred = Math.min(cells, world.bodies[from].cells);
  world.bodies[from].cells -= transferred; world.bodies[to].cells += transferred;
  recordEconomicChange(world, before, label, from);
  remember(world, from, { kind: 'agreement', other: to, amount: cells, outcome: `Transferred ${cells} cells under ${label}.` });
  remember(world, to, { kind: 'agreement', other: from, amount: cells, outcome: `Received ${cells} cells under ${label}.` });
}
/** Called only after exact counterpart acceptance has passed turn validation. */
export function acceptOfferDraft(state: SocietyState, world: WorldState, offer: Offer, nowMs: number): string | null {
  const problem = termsProblem(state, world, offer.terms);
  if (problem) return problem;
  if (!makeRoom(state.agreements, L.agreements, (a) => a.status === 'fulfilled' || (a.status === 'breached' && a.terms.kind === 'work'))) return 'agreement_capacity';
  const terms = offer.terms;
  const agreement: Agreement = { id: nextSocietyId(state, 'agreement'), offerId: offer.id, terms: structuredClone(terms),
    status: terms.kind === 'transfer' ? 'fulfilled' : 'active', acceptedAtMs: nowMs, acceptedAtWatch: watchNumber(world),
    acceptedAfterEventSequence: world.economy.nextEventSequence,
    progress: 0, completedAtMs: terms.kind === 'transfer' ? nowMs : null, evidenceIds: [], debtId: null };
  if (terms.kind !== 'work') {
    transfer(world, terms.from, terms.to, terms.cells, `agreement:${agreement.id}`);
    if (terms.kind === 'loan') {
      const sequence = world.economy.nextDebtSequence++;
      const debtId = `${world.day}-${world.watch}-${terms.from}${terms.to}-${sequence}`;
      const paid = world.economy.debts.filter((d) => d.status === 'paid').slice(-49);
      world.economy.debts = [...world.economy.debts.filter((d) => d.status !== 'paid'), ...paid,
        { id: debtId, lender: terms.from, borrower: terms.to, principal: terms.cells, remaining: terms.cells,
          issuedDay: world.day, dueDay: terms.dueDay, status: 'open' }];
      agreement.debtId = debtId;
      nudge(world, terms.to, terms.from, 'debt', terms.cells);
    }
    nudge(world, terms.to, terms.from, 'trust', 1);
  }
  offer.status = 'accepted'; offer.acceptedAtMs = nowMs;
  state.agreements.push(agreement);
