export function parseSocietyState(raw: unknown): { ok: true; state: SocietyState } | { ok: false; code: string } {
  const parsed = state.safeParse(raw);
  if (!parsed.success) return { ok: false, code: 'invalid_society_state' };
  const s = parsed.data;
  const ids: string[] = [];
  for (const r of RESIDENTS) {
    const m = s.minds[r.id];
    if (!m || m.id !== r.id) return { ok: false, code: 'invalid_mind_identity' };
    for (const e of m.memories) {
      ids.push(e.id);
      if (e.kind === 'interpretation' && !e.refs.length) return { ok: false, code: 'unevidenced_memory' };
    }
    if (new Set(m.memories.map((e) => e.id)).size !== m.memories.length) return { ok: false, code: 'duplicate_memory' };
    if (m.project) {
      ids.push(m.project.id, ...m.project.steps.map((p) => p.id));
      if (m.project.steps.some((p) => p.intent.actor !== r.id || (p.status === 'done' && !p.evidenceId))) return { ok: false, code: 'invalid_project_evidence' };
      if (m.project.steps.some((p) => !(PLANNABLE_VERBS as readonly string[]).includes(p.intent.verb)
        || p.at === 'breach' || p.intent.room === 'breach' || (p.at !== null && p.intent.verb === 'go'))) return { ok: false, code: 'invalid_executable_plan' };
      if (m.project.status === 'completed' && (!m.project.steps.length || m.project.steps.some((p) => p.status !== 'done'))) return { ok: false, code: 'uncompleted_project_steps' };
    }
  }
  const busy = new Set<string>();
  for (const c of s.conversations) {
    ids.push(c.id, ...c.turns.map((t) => t.id));
    if (c.participants[0] === c.participants[1] || c.expiresAtMs <= c.createdAtMs) return { ok: false, code: 'invalid_conversation' };
    if (c.status === 'open' ? !c.participants.includes(c.nextSpeaker!) || c.turns.length >= L.turns : c.nextSpeaker !== null) return { ok: false, code: 'invalid_next_speaker' };
    if (c.turns.some((t, i) => t.index !== i || t.speaker !== c.participants[i % 2])) return { ok: false, code: 'invalid_turn_order' };
    if (c.appraisedThrough?.some((index, member) => index !== -1
      && (!c.turns[index] || c.turns[index].speaker === c.participants[member]))) return { ok: false, code: 'invalid_appraisal_watermark' };
    if (c.status === 'open' && c.nextSpeaker !== c.participants[c.turns.length % 2]) return { ok: false, code: 'invalid_next_speaker' };
    if (c.status === 'open') for (const p of c.participants) { if (busy.has(p)) return { ok: false, code: 'overlapping_conversation' }; busy.add(p); }
  }
  for (const o of s.offers) {
    ids.push(o.id);
    const parties = o.terms.kind === 'work' ? [o.terms.worker, o.terms.payer] : [o.terms.from, o.terms.to];
    if (o.proposer === o.counterpart || new Set(parties).size !== 2 || !parties.includes(o.proposer) || !parties.includes(o.counterpart)
      || (o.terms.kind !== 'work' && o.terms.cells <= 0)) return { ok: false, code: 'invalid_offer_parties' };
    if (o.status === 'open') {
      const c = s.conversations.find((c) => c.id === o.conversationId);
      if (!c || c.status !== 'open' || !c.participants.includes(o.proposer) || !c.participants.includes(o.counterpart)) return { ok: false, code: 'orphan_open_offer' };
    }
    if ((o.status === 'accepted') !== (o.acceptedAtMs !== null)) return { ok: false, code: 'invalid_acceptance' };
  }
  for (const a of s.agreements) {
    ids.push(a.id);
    const participants = a.terms.kind === 'work' ? [a.terms.worker, a.terms.payer] : [a.terms.from, a.terms.to];
    if (new Set(participants).size !== 2 || (a.terms.kind !== 'work' && a.terms.cells <= 0)) return { ok: false, code: 'invalid_agreement_parties' };
    if (a.terms.kind === 'work' && a.progress > a.terms.units) return { ok: false, code: 'invalid_work_progress' };
    if (a.terms.kind === 'work' && (a.progress !== a.evidenceIds.length || new Set(a.evidenceIds).size !== a.evidenceIds.length
      || (['payment_due', 'fulfilled'].includes(a.status) && a.progress !== a.terms.units))) return { ok: false, code: 'invalid_work_evidence' };
    if (a.status === 'fulfilled' && a.completedAtMs === null) return { ok: false, code: 'missing_fulfillment' };
    if (a.terms.kind === 'loan' ? a.debtId === null : a.debtId !== null) return { ok: false, code: 'invalid_debt_reference' };
    const original = s.offers.find((o) => o.id === a.offerId);
    if (original && (original.status !== 'accepted' || JSON.stringify(original.terms) !== JSON.stringify(a.terms))) return { ok: false, code: 'agreement_terms_changed' };
  }
  if (new Set(ids).size !== ids.length) return { ok: false, code: 'duplicate_society_id' };
  if (ids.some((id) => { const match = /^(?:project|step|memory|conversation|turn|offer|agreement):(\d+)$/.exec(id); return !match || Number(match[1]) >= s.nextId; })) return { ok: false, code: 'invalid_id_sequence' };
  return { ok: true, state: JSON.parse(JSON.stringify(s)) as SocietyState };
}

import { RESIDENTS, type ResidentId } from '../residents';
import type { WorldState } from '../engine/state';
import { SOCIETY_LIMITS as L, SOCIETY_VERSION, type Evidence, type SocietyState } from './types';

export function watchNumber(world: Pick<WorldState, 'day' | 'watch'>): number {
  return world.day * 4 + world.watch - 1;
}
export function createSocietyState(world: WorldState, nowMs: number): SocietyState {
  if (!Number.isSafeInteger(nowMs) || nowMs < 0) throw new RangeError('Invalid society timestamp');
  const minds = {} as SocietyState['minds'];
  for (const { id } of RESIDENTS) minds[id] = { id, revision: 0,
      lastAttemptAtMs: null, lastSuccessAtMs: null, lastAppliedSequence: -1,
      lastPhysicalWatch: watchNumber(world) - 1, project: null, memories: [] };
  return { version: SOCIETY_VERSION, revision: 0, nextId: 0, createdAtMs: nowMs, minds,
    conversations: [], offers: [], agreements: [] };
}
/** Helpers below mutate only a private draft owned by a pure public operation. */
export function nextSocietyId(state: SocietyState, kind: string): string { return `${kind}:${state.nextId++}`; }
export function addEvidence(state: SocietyState, actor: ResidentId, entry: Evidence): void {
  const m = state.minds[actor];
  if (m.memories.some((e) => e.id === entry.id)) return;
  m.memories.push(entry);
  m.memories = m.memories.slice(-L.memories);
  m.revision += 1;
}
export function evidence(state: SocietyState, actor: ResidentId, world: WorldState, nowMs: number,
  kind: Evidence['kind'], text: string, refs: string[] = [], source: ResidentId | null = null, importance = 3): string {
  const id = nextSocietyId(state, 'memory');
  addEvidence(state, actor, { id, kind, text: text.slice(0, 400), refs: refs.slice(0, 6),
    atWatch: watchNumber(world), createdAtMs: nowMs, importance, source });
  return id;
}
export function expireDraft(state: SocietyState, world: WorldState, nowMs: number): boolean {
  let changed = false;
  for (const c of state.conversations) {
    if (c.status !== 'open' || c.expiresAtMs > nowMs) continue;
    c.status = 'expired'; c.nextSpeaker = null; c.revision += 1; changed = true;
    for (const p of c.participants) evidence(state, p, world, nowMs, 'observation',
      'The conversation expired without another reply. Silence did not accept any terms.', [c.id]);
  }
  for (const o of state.offers) {
    if (o.status !== 'open') continue;
    const c = state.conversations.find((c) => c.id === o.conversationId);
    if (o.expiresAtWatch > watchNumber(world) && c?.status === 'open') continue;
    o.status = 'expired'; changed = true;
    for (const p of [o.proposer, o.counterpart]) evidence(state, p, world, nowMs, 'observation', 'The offer expired without acceptance.', [o.id]);
  }
  return changed;
}
export function expireSocietyState(state: SocietyState, world: WorldState, nowMs: number): SocietyState {
  const next = structuredClone(state);
  if (!expireDraft(next, world, nowMs)) return state;
  next.revision += 1;
  return next;
}
/** Calling a provider is observable even if it later fails. It is not a thought. */
export function markSocietyAttempt(state: SocietyState, actor: ResidentId, nowMs: number): SocietyState {
  if (!Number.isSafeInteger(nowMs) || nowMs < 0) throw new RangeError('Invalid attempt timestamp');
  if ((state.minds[actor].lastAttemptAtMs ?? -1) >= nowMs) return state;
  const next = structuredClone(state);
  next.minds[actor].lastAttemptAtMs = nowMs; next.revision += 1;
  return next;
}
/** Closed history is bounded here; the runtime may archive immutable results. */
export function makeRoom<T>(items: T[], limit: number, canRemove: (item: T) => boolean): boolean {
  while (items.length >= limit) {
    const index = items.findIndex(canRemove);
    if (index < 0) return false;
    items.splice(index, 1);
  }
  return true;
}

import { RESIDENTS, RESIDENT_BY_ID, type ResidentId } from '../residents';
import { ROOMS } from '../rooms';
import { AXES } from '../weave';
import { knowledgeFor, sharedBondsFor } from '../engine/knowledge';
import { decodeIntentFor, VERBS, type Intent } from '../engine/verbs';
import { outstanding, yieldFor, type MemoryFact } from '../engine/economy';
import type { WorldState } from '../engine/state';
import { acceptOfferDraft, minimumWorkDeadline, parties, promisedCells, termsProblem, workDeadlineProblem } from './economy';
import { canSpendCells, maxSpendableCells } from './money';
import { parseTurnResponse } from './schema';
import { evidence, expireDraft, makeRoom, nextSocietyId, watchNumber } from './state';
import { SOCIETY_LIMITS as L, PLANNABLE_VERBS, type PreparedTurn, type SocietyResult, type SocietyState, type TurnOptions, type TurnResponse } from './types';

const SYSTEM = `You are SELF. Pursue your wants. If conversation=null, initiate contact for your own goal; nobody has spoken to you. Otherwise answer the actual last message on your turn. Start a purpose if absent; keep useful plans. JSON: omit unused fields. Social goals may use steps:[]. Message=speech, never a verb. Use schema IDs. Claims are not facts or consent. Offer/respond needs message close:false; choose one. Work cells=total for all units. One action/watch: at=travel first; go.room=place; repay.target=person. Public goals/messages visible; why private. English, concise.`;

function ownConversation(state: SocietyState, actor: ResidentId, nowMs: number) {
  return state.conversations.find((c) => c.status === 'open' && c.expiresAtMs > nowMs && c.participants.includes(actor));
}
/** Content identity survives the body's bounded memory window shifting. This
 * labels an existing personal record; it does not manufacture a past event. */
export function bodyMemoryId(actor: ResidentId, fact: MemoryFact): string {
  const bytes = new TextEncoder().encode(JSON.stringify([fact.day, fact.watch, fact.kind,
    fact.other ?? null, fact.amount ?? null, fact.resource ?? null, fact.outcome]));
  let hash = 0xcbf29ce484222325n;
  for (const byte of bytes) hash = BigInt.asUintN(64, (hash ^ BigInt(byte)) * 0x100000001b3n);
  return `body:${actor}:${fact.day}:${fact.watch}:${hash.toString(16)}`;
}
export function prepareSocietyTurn(state: SocietyState, world: WorldState, actor: ResidentId, options: TurnOptions): PreparedTurn {
