   *  the surface on the other side of it. */
  back: string;
  backGrain: string;
  /** What is underfoot. */
  floor: string;
  floorEdge: string;
  /** Light in this room, and what it warms. */
  light: string;
  glow: string;
  /** Objects, before their own tint. */
  matter: string;
  matterEdge: string;
};

