import {
  fetchHabitatArchive, fetchHabitatObserverUpdate, fetchHabitatStatus, habitatReadError,
  type ArchiveEntry, type ObserverState, type RuntimeStatus,
} from './live';

const PUBLIC_RUNTIME = 'https://aleetreny-habitat-runtime.alejandrotreny100.workers.dev';
const POLL_MS = 45_000;
type Connection = 'connecting' | 'live' | 'stale' | 'offline';

/** Reads only: opening the observer never advances the world or invokes a model. */
export function useHabitatLive() {
  const base = import.meta.env.DEV
    ? `${window.location.origin}/__habitat` : runtimeConfig.habitatRuntimeUrl || PUBLIC_RUNTIME;
  const [world, setWorld] = useState<ObserverState | null>(null);
  const [status, setStatus] = useState<RuntimeStatus | null>(null);
  const [statusError, setStatusError] = useState<string | null>(null);
  const [connection, setConnection] = useState<Connection>('connecting');
  const [lastConnectedAt, setLastConnectedAt] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [refreshId, setRefreshId] = useState(0);
  const connected = useRef(false);
  const etag = useRef<string | null>(null);
  const [selectedDay, setSelectedDay] = useState<number | null>(null);
  const archiveDay = selectedDay ?? world?.snapshot.day ?? 100;
  const [archiveResult, setArchiveResult] = useState<{ day: number; entries: ArchiveEntry[] } | null>(null);
  const [archiveLoading, setArchiveLoading] = useState(false);
  const [archiveError, setArchiveError] = useState<string | null>(null);
  const refresh = useCallback(() => setRefreshId((value) => value + 1), []);

  useEffect(() => {
    const controller = new AbortController();
    let fetching = false;
    const read = async () => {
      if (fetching || document.hidden) return;
      fetching = true;
      const deadline = AbortSignal.any([controller.signal, AbortSignal.timeout(15_000)]);
      // Auxiliary clock failure must never discard a successfully read world.
      const observer = fetchHabitatObserverUpdate(base, { signal: deadline, etag: etag.current }).then((update) => {
        if (controller.signal.aborted) return;
        etag.current = update.etag;
        if (!update.unchanged) setWorld((previous) => !previous || update.world.worldRevision >= previous.worldRevision ? update.world : previous);
        connected.current = true;
        setLastConnectedAt(Date.now());
        setConnection('live');
        setError(null);
      }).catch((reason: unknown) => {
        if (controller.signal.aborted) return;
        setConnection(connected.current ? 'stale' : 'offline');
        setError(habitatReadError(reason, 'world'));
      });
      const clock = fetchHabitatStatus(base, { signal: deadline }).then((next) => {
        if (controller.signal.aborted) return;
        setStatus(next);
        setStatusError(null);
      }).catch(() => {
        if (controller.signal.aborted) return;
        setStatus(null);
        setStatusError('The world clock could not be checked.');
      });
      await Promise.all([observer, clock]);
      fetching = false;
    };
    const interval = window.setInterval(() => { void read(); }, POLL_MS);
    const visible = () => { if (!document.hidden) void read(); };
    document.addEventListener('visibilitychange', visible);
    void read();
    return () => {
      controller.abort();
      window.clearInterval(interval);
      document.removeEventListener('visibilitychange', visible);
    };
  }, [base, refreshId]);

  const revision = world?.worldRevision;
  useEffect(() => {
    if (revision === undefined) return;
    const controller = new AbortController();
    let active = true;
    void Promise.resolve().then(async () => {
      if (!active) return;
      setArchiveLoading(true);
      setArchiveError(null);
      try {
        const entries = await fetchHabitatArchive(base, archiveDay, {
          signal: AbortSignal.any([controller.signal, AbortSignal.timeout(15_000)]),
        });
        if (active) setArchiveResult({ day: archiveDay, entries });
      } catch (reason) {
        if (active) setArchiveError(habitatReadError(reason, 'journal'));
      } finally {
        if (active) setArchiveLoading(false);
      }
    });
    return () => { active = false; controller.abort(); };
  }, [base, archiveDay, revision, refreshId]);

  const currentDay = world?.snapshot.day ?? 100;
  const setArchiveDay = useCallback((day: number) => {
    setSelectedDay(day === currentDay ? null : Math.max(100, Math.min(currentDay, day)));
  }, [currentDay]);

  return {
    snapshot: world?.snapshot ?? null, relationships: world?.relationships ?? [], society: world?.society ?? null, agency: world?.agency ?? null,
    status, statusError, connection, lastConnectedAt, error, refresh, archiveDay, setArchiveDay,
    archive: archiveResult?.day === archiveDay ? archiveResult.entries : [],
    archiveLoading, archiveError,
  };
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { ROOM_BY_ID, type RoomId } from './rooms';
import type { HabitatSnapshot } from './snapshot';
import { visibleRoom } from './room-art';
import { usePageVisible, useReducedMotion } from './observer-preferences';

/** Corridors remain in the canonical graph; the room observer folds them away. */
export function observerNeighbors(room: RoomId): RoomId[] {
  const candidates = new Set<RoomId>();
  const visit = (id: RoomId, visited: Set<RoomId>) => {
    if (id === 'breach' || visited.has(id)) return;
    visited.add(id);
    if (id === 'longwalk' || id === 'row') ROOM_BY_ID[id].connects.forEach((next) => visit(next, visited));
    else if (id !== room) candidates.add(id);
  };
  ROOM_BY_ID[room].connects.forEach((id) => visit(id, new Set([room])));
  return [...candidates];
}

const neighbors = new Map<RoomId, RoomId[]>();
function onward(room: RoomId) {
  if (!neighbors.has(room)) neighbors.set(room, observerNeighbors(room));
  return neighbors.get(room)!;
}

/** An unbroken, deterministic walk: each step extends the previous route.
 * No cycle restarts at home, and this clock never writes a world event. */
export function observerPresence(snapshot: HabitatSnapshot, seconds: number, origins = snapshot.people): HabitatSnapshot {
  const people = snapshot.people.map((person, index) => {
    const home = visibleRoom(origins.find((origin) => origin.id === person.id)?.room ?? person.room);
    const beat = Math.floor(Math.max(0, seconds) / (34 + index % 7 * 3));
    let room = home, previous = home;
    for (let step = 0; step < beat; step++) {
      const candidates = onward(room);
      const continuing = candidates.filter((id) => id !== previous);
      const visits = continuing.length ? continuing : candidates;
      if (!visits.length) break;
      previous = room;
      room = visits[(index * 7 + step * 3) % visits.length]!;
    }
    return { ...person, room, doing: room !== visibleRoom(person.room) ? 'taking a walk' : person.doing };
  });
  return { ...snapshot, people, rooms: snapshot.rooms.map((room) => ({ ...room, occupants: people.filter((person) => person.room === room.id).map((person) => person.id) })) };
}

export function useObserverPresence(snapshot: HabitatSnapshot | null, enabled = true): HabitatSnapshot | null {
  const reduced = useReducedMotion();
  const visible = usePageVisible();
  const [seconds, setSeconds] = useState(0);
  const elapsed = useRef(0);
  const lastSteps = useRef('');
  // Keep the presentation route when a newly committed world moves someone.
  const [origins, setOrigins] = useState<HabitatSnapshot['people'] | null>(null);
  if (snapshot && !origins) setOrigins(snapshot.people);
  const hasSnapshot = Boolean(snapshot);
  useEffect(() => {
    if (!hasSnapshot || !enabled || reduced || !visible) return;
    const timer = window.setInterval(() => {
      elapsed.current += 1;
      const steps = Array.from({ length: 7 }, (_, index) => Math.floor(elapsed.current / (34 + index * 3))).join(',');
      if (steps !== lastSteps.current) { lastSteps.current = steps; setSeconds(elapsed.current); }
    }, 1000);
    return () => window.clearInterval(timer);
  }, [hasSnapshot, enabled, reduced, visible]);
  // Only a room crossing changes React state; idle clock ticks stay in refs.
  return useMemo(() => snapshot ? observerPresence(snapshot, seconds, origins ?? snapshot.people) : null,
    [snapshot, origins, seconds]);
}

// What is between them.
//
// Six directed axes, because I may trust you a great deal more than you trust me
// and that difference is half of all human drama. Plus a written line per pair,
// because no number captures what is between two particular people: the axes are
// the instrument and the line is the person.
//
// The graph the twenty-five carried aboard is clustered far past what chance would
// produce, and nothing explains it. Not something withheld from the residents —
// something that does not exist. The measurement lives here, and in weave.test.ts,
// so that editing a bond cannot quietly destroy the fact.

import { mulberry32 } from './random';
import { AUTHORED, BASELINE, SAME_CLUSTER_BONUS, type AxisSet, type Directed } from './axes';
import { RESIDENTS, type Cluster, type ResidentId } from './residents';

export const AXES = [
  'trust', 'affection', 'admiration', 'debt', 'resentment', 'desire',
] as const;
export type Axis = (typeof AXES)[number];

export type Degree = 'nothing' | 'by-sight' | 'spoken' | 'real' | 'latent';

export type Bond = {
  from: ResidentId;
  to: ResidentId;
  degree: 'real';
  /** What no scale captures. Revised when something changes between them. */
  line: string;
};

export type LatentBond = {
  from: ResidentId;
  to: ResidentId;
  degree: 'latent';
  /** Always `from`. One of them knows and the other does not. */
  knower: ResidentId;
  line: string;
  /** What would have to happen in the world for it to come out. A latent bond
   *  with no route is a dotted edge that never resolves, which would be a cheat. */
  route: string;
};

