import { z } from 'zod';

export const GENESIS_RESIDENT_COUNT = 25 as const;
export const MAX_RESIDENTS = 25 as const;
export const HABITAT_SCHEMA_VERSION = 1 as const;
export const SQL_SCHEMA_VERSION = 7 as const;

export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [key: string]: JsonValue };

export const jsonValueSchema: z.ZodType<JsonValue> = z.lazy(() =>
  z.union([
    z.null(),
    z.boolean(),
    z.number(),
    z.string(),
    z.array(jsonValueSchema),
    z.record(z.string(), jsonValueSchema),
  ]),
);

export const simInstantSchema = z.strictObject({
  day: z.number().int().nonnegative(),
  minute: z.number().int().min(0).max(1439),
});

export type SimInstant = z.infer<typeof simInstantSchema>;

const subjectSchema = z.strictObject({
  kind: z.string().min(1).max(64),
  id: z.string().min(1).max(128),
});

export const cognitionJobSchema = z.strictObject({
  schemaVersion: z.literal(HABITAT_SCHEMA_VERSION),
  jobId: z.string().min(1).max(160),
  habitatId: z.string().min(1).max(80),
  origin: z.strictObject({
    kind: z.literal('alarm'),
    runId: z.string().min(1).max(160),
  }),
  cause: z.strictObject({
    worldRevision: z.number().int().nonnegative(),
    simTime: simInstantSchema,
    eventId: z.string().min(1).max(160).optional(),
  }),
  kind: z.string().min(1).max(80),
  subjects: z.array(subjectSchema).min(1).max(MAX_RESIDENTS),
  pressure: z.number().min(0).max(1),
  createdAtMs: z.number().int().nonnegative(),
  prompt: z.strictObject({
    system: z.string().min(1).max(24_000),
    user: z.string().min(1).max(24_000),
  }),
  outputContract: z.strictObject({
    name: z.string().regex(/^[a-z][a-z0-9_]{0,63}$/),
    version: z.number().int().positive(),
    schemaHash: z.string().min(8).max(128),
    jsonSchema: jsonValueSchema.refine(
      (value) => value !== null && typeof value === 'object' && !Array.isArray(value),
      'jsonSchema must be an object',
    ),
  }),
  maxOutputTokens: z.number().int().min(1).max(1536),
});

export type CognitionJob = z.infer<typeof cognitionJobSchema>;

export const adminCommandSchema = z.strictObject({
  commandId: z.string().min(8).max(160),
  issuedAtMs: z.number().int().nonnegative(),
  expectedControlRevision: z.number().int().nonnegative().optional(),
  reason: z.string().min(1).max(240).optional(),
});

export type AdminCommand = z.infer<typeof adminCommandSchema>;

export const archiveFilterSchema = z.strictObject({
  day: z.number().int().nonnegative(),
  room: z.string().min(1).max(64).optional(),
  person: z.string().min(1).max(8).optional(),
});

export type ArchiveFilter = z.infer<typeof archiveFilterSchema>;

export type ProviderId = 'workers-ai' | 'groq';

export type ProviderUsage = {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
  neurons?: number;
  /** Already included in outputTokens, never added a second time. */
  reasoningTokens?: number;
  /** Set when the provider supplied malformed or contradictory usage fields. */
  incomplete?: boolean;
};

export type ProviderAttemptResult =
  | {
      ok: true;
      provider: ProviderId;
      model: string;
      attemptId: string;
      providerRequestId?: string;
      payload: JsonValue;
      usage: ProviderUsage;
      latencyMs: number;
    }
  | {
      ok: false;
      provider: ProviderId;
      model: string;
      attemptId: string;
      kind:
        | 'quota-exhausted'
        | 'rate-limited'
        | 'timeout'
        | 'unavailable'
        | 'invalid-response'
        | 'authentication'
        | 'misconfigured'
        | 'policy-blocked'
        | 'rejected';
      retryable: boolean;
      retryAtMs?: number;
      detailCode?: string;
      /** The provider can report billable usage even when its output is invalid. */
      usage?: ProviderUsage;
      providerRequestId?: string;
      latencyMs: number;
    };

export type RouterResult =
  | { status: 'completed'; attempts?: ProviderAttemptResult[]; result: Extract<ProviderAttemptResult, { ok: true }> }
  | { status: 'deferred'; retryAtMs: number; reasons: ProviderAttemptResult[] }
  | { status: 'rejected'; reasons: ProviderAttemptResult[] };

// Env also contains bindings and platform-injected test values, so this schema
// intentionally selects only runtime policy fields instead of rejecting extras.
export const runtimeConfigSchema = z.object({
  HABITAT_ID: z.string().min(1),
  PUBLIC_ORIGIN: z.literal('https://aleetreny.github.io'),
  TICK_INTERVAL_MS: z.coerce.number().int().refine(
    (value) => value === 6 * 60 * 60 * 1_000,
    'one watch must equal exactly six real hours',
  ),
  MAX_COGNITIONS_PER_ALARM: z.coerce.number().int().min(1).max(1),
  WORKERS_AI_MODEL: z.enum(['@cf/google/gemma-4-26b-a4b-it', '@cf/qwen/qwen3-30b-a3b-fp8', '@cf/openai/gpt-oss-120b']),
  WORKERS_AI_DAILY_NEURONS_LIMIT: z.coerce.number().int().min(1).max(10_000),
  GROQ_MODEL: z.literal('openai/gpt-oss-20b'),
  GROQ_DAILY_TOTAL_TOKENS_LIMIT: z.coerce.number().int().min(1).max(200_000),
});

export type RuntimeConfig = z.infer<typeof runtimeConfigSchema>;

export function parseRuntimeConfig(env: unknown): RuntimeConfig {
  return runtimeConfigSchema.parse(env);
}

/** A late provider response cannot escape this promise and become an action.
 * Dispatch may already have incurred usage, so callers retain the reservation.
 */
export async function withProviderDeadline<T>(pending: Promise<T>, timeoutMs: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      pending,
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => {
          const error = new Error('Provider response deadline exceeded.');
          error.name = 'ProviderTimeout';
          reject(error);
        }, timeoutMs);
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
}

import type { CognitionJob } from '../contracts';
import { GROQ_MODEL } from './groq';
import { estimateTokens } from './shared';
import { tokenizeGroqOrdinary } from './groq-tokenizer';

export const GROQ_FRAMING_MARGIN = 128;

/** Exact ordinary tokens in authored components, plus an explicit provisional
 * provider-framing allowance. This is not an exact server-side prompt count.
 * Unknown models, excessive text or tokenizer failure keep the full UTF-8 byte
 * allowance. The historical625-token static evidence remains archived.
 */
export async function estimateGroqInputTokens(job: CognitionJob, model: string = GROQ_MODEL): Promise<number> {
  const parts = [job.prompt.system, job.prompt.user, JSON.stringify(job.outputContract.jsonSchema)];
  const fallback = () => estimateTokens(parts.join('\n'));
  if (model !== GROQ_MODEL) return fallback();
  const tokens = await tokenizeGroqOrdinary(parts);
  return tokens ? tokens.reduce((n, part) => n + part.length, 0) + GROQ_FRAMING_MARGIN : fallback();
}

import { init, Tiktoken } from 'tiktoken/lite/init';
import ranks from 'tiktoken/encoders/o200k_base';
import wasm from 'tiktoken/lite/tiktoken_bg.wasm';

export const GROQ_TOKENIZER_MAX_BYTES = 24_000;
type OrdinaryEncoder = Pick<Tiktoken, 'encode_ordinary'>;

/** One immutable encoder per isolate. Never retain prompts or count results.
 * Initialization failures are cached until isolate replacement, preventing an
 * allocation/retry storm. No WebAssembly instance is created on module import.
 */
export function createOrdinaryTokenizer(load: () => Promise<OrdinaryEncoder>) {
  let pending: Promise<OrdinaryEncoder | null> | undefined;
  return async (parts: readonly string[]): Promise<Uint32Array[] | null> => {
    // Bound before initialization and before pathological BPE work. Do not
    // truncate a payload or imply that only its prefix will reach the provider.
    if (parts.length > 3 || parts.some(text => text.length > GROQ_TOKENIZER_MAX_BYTES)
      || parts.reduce((n, text) => n + new TextEncoder().encode(text).byteLength, 0) > GROQ_TOKENIZER_MAX_BYTES) return null;
    try {
      pending ??= Promise.resolve().then(load).catch(() => null);
      const encoder = await pending;
      return encoder ? parts.map(text => encoder.encode_ordinary(text)) : null;
    } catch {
      // A tokenizer error affects accounting strategy, never world state or
      // provider control. Byte accounting remains available to the caller.
      return null;
    }
  };
}

/** o200k_harmony uses the same ranks and regex as o200k_base for ordinary
 * text. Literal Harmony delimiters must not become privileged special tokens.
 * Sources and verified rank SHA256 are recorded in the research note.
 */
export const tokenizeGroqOrdinary = createOrdinaryTokenizer(async () => {
  await init(async imports => new WebAssembly.Instance(wasm, imports));
  return new Tiktoken(ranks.bpe_ranks, {}, ranks.pat_str);
});

import type { CognitionJob, ProviderAttemptResult } from '../contracts';
import { parseStructuredPayload, sanitizeUsage } from './shared';

export const GROQ_MODEL = 'openai/gpt-oss-20b' as const;
export const GROQ_MAX_RESPONSE_BYTES = 256 * 1024;
const GROQ_ENDPOINT = 'https://api.groq.com/openai/v1/chat/completions';

type Fetcher = (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;

class ResponseTooLargeError extends Error {}

/** The output token cap does not bound HTTP error bodies. Count decoded stream
 * bytes even without Content-Length, and keep the request deadline through EOF.
 * No partial body can establish usage or become a resident's response. */
async function boundedJson(response: Response, signal: AbortSignal): Promise<unknown> {
  const declared = response.headers.get('content-length');
  if (declared !== null && Number(declared) > GROQ_MAX_RESPONSE_BYTES) {
    void response.body?.cancel().catch(() => {});
    throw new ResponseTooLargeError();
  }
  if (!response.body) throw new SyntaxError('Empty provider response');
  const reader = response.body.getReader();
  const cancel = () => { void reader.cancel().catch(() => {}); };
  signal.addEventListener('abort', cancel, { once: true });
  try {
    const chunks: Uint8Array[] = [];
    let bytes = 0;
    for (;;) {
      signal.throwIfAborted();
      const { done, value } = await reader.read();
      signal.throwIfAborted();
      if (done) break;
      bytes += value.byteLength;
      if (bytes > GROQ_MAX_RESPONSE_BYTES) throw new ResponseTooLargeError();
      chunks.push(value);
    }
    const body = new Uint8Array(bytes);
    let offset = 0;
    for (const chunk of chunks) { body.set(chunk, offset); offset += chunk.byteLength; }
    return JSON.parse(new TextDecoder().decode(body));
  } catch (error) {
    cancel();
    throw error;
  } finally {
    signal.removeEventListener('abort', cancel);
    reader.releaseLock();
  }
}

function retryAt(response: Response, now: number): number {
  const raw = response.headers.get('retry-after');
  if (!raw) return now + 60_000;
  const seconds = Number(raw);
  if (Number.isFinite(seconds)) return now + Math.max(1, seconds) * 1_000;
  const timestamp = Date.parse(raw);
  return Number.isFinite(timestamp) ? Math.max(now + 1_000, timestamp) : now + 60_000;
}

type GroqResponse = {
  id?: unknown;
  choices?: Array<{ finish_reason?: string; message?: { content?: unknown } }>;
  usage?: Parameters<typeof sanitizeUsage>[0];
  error?: { code?: unknown; type?: unknown; usage?: Parameters<typeof sanitizeUsage>[0] };
  x_groq?: { id?: unknown; usage?: Parameters<typeof sanitizeUsage>[0] };
};

export async function runGroq(input: {
  apiKey: string | undefined;
  job: CognitionJob;
  attemptId: string;
  model: string;
  fetcher?: Fetcher;
  now?: () => number;
}): Promise<ProviderAttemptResult> {
  const now = input.now ?? Date.now;
  const startedAt = now();

  if (input.model !== GROQ_MODEL) {
    return failure(input, 'policy-blocked', false, startedAt, now, 'model_not_allowed');
  }
  if (!input.apiKey) {
    return failure(input, 'misconfigured', false, startedAt, now, 'missing_api_key');
  }

  const fetcher = input.fetcher ?? fetch;
  const signal = AbortSignal.timeout(45_000);
  let response: Response;
  try {
    response = await fetcher(GROQ_ENDPOINT, {
      method: 'POST',
      headers: {
        authorization: `Bearer ${input.apiKey}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        model: GROQ_MODEL,
        messages: [
          { role: 'system', content: input.job.prompt.system },
          { role: 'user', content: input.job.prompt.user },
        ],
        reasoning_effort: 'low',
        max_completion_tokens: input.job.maxOutputTokens,
        stream: false,
        response_format: {
          type: 'json_schema',
          json_schema: {
            name: input.job.outputContract.name,
            // The compact society wire has optional union members. Local
            // validation remains mandatory; the legacy intent stays strict.
            strict: input.job.outputContract.name !== 'society_turn',
            schema: input.job.outputContract.jsonSchema,
          },
        },
      }),
      signal,
    });
  } catch (error) {
    const timeout = error instanceof DOMException && error.name === 'TimeoutError';
    return failure(
      input,
      timeout ? 'timeout' : 'unavailable',
      true,
      startedAt,
      now,
      timeout ? 'request_timeout' : 'network_error',
    );
  }

  let body: GroqResponse | undefined;
  let bodyError: 'response_too_large' | undefined;
  try {
    const decoded = await boundedJson(response, signal);
    if (decoded !== null && typeof decoded === 'object' && !Array.isArray(decoded)) body = decoded;
  } catch (error) {
    if (signal.aborted) return failure(input, 'timeout', true, startedAt, now, 'request_timeout');
    if (error instanceof ResponseTooLargeError) bodyError = 'response_too_large';
    // HTTP status remains authoritative even when its body is not usable.
  }
  const usage = sanitizeUsage(body?.usage ?? body?.x_groq?.usage ?? body?.error?.usage);
  const requestId = body?.x_groq?.id ?? body?.id;
  const metadata = { usage, ...(typeof requestId === 'string' ? { providerRequestId: requestId.slice(0, 160) } : {}) };
  const reject = (kind: Extract<ProviderAttemptResult, { ok: false }>['kind'], retryable: boolean, code?: string) =>
    ({ ...failure(input, kind, retryable, startedAt, now, code), ...metadata });

  if (!response.ok) {
    const errorCode = body?.error?.code ?? body?.error?.type;
    const detailCode = typeof errorCode === 'string' ? errorCode.slice(0, 80) : bodyError;
    const latencyMs = now() - startedAt;
    if (detailCode === 'json_validate_failed') {
      return reject('invalid-response', true, detailCode);
    }
    if (detailCode === 'blocked_api_access') {
      return {
        ok: false,
        provider: 'groq',
        model: GROQ_MODEL,
        attemptId: input.attemptId,
        kind: 'policy-blocked',
        retryable: false,
        ...(detailCode ? { detailCode } : {}),
        latencyMs,
        ...metadata,
      };
    }
    if (response.status === 429) {
      return {
        ok: false,
        provider: 'groq',
        model: GROQ_MODEL,
        attemptId: input.attemptId,
        kind: 'rate-limited',
        retryable: true,
        retryAtMs: retryAt(response, now()),
        ...(detailCode ? { detailCode } : {}),
        latencyMs,
        ...metadata,
      };
    }
    if (response.status === 401 || response.status === 403) {
      return reject('authentication', false, detailCode);
    }
    if (response.status >= 500) {
      return reject('unavailable', true, detailCode);
    }
    if (response.status === 422) {
      return reject('invalid-response', true, detailCode);
    }
    return reject('rejected', false, detailCode);
  }

  if (bodyError) return reject('invalid-response', true, bodyError);
  try {
    const content = body?.choices?.[0]?.message?.content;
    if (body?.choices?.[0]?.finish_reason === 'length') {
      return reject('invalid-response', true, 'output_truncated');
    }
    const payload = parseStructuredPayload(content);
    return {
      ok: true,
      provider: 'groq',
      model: GROQ_MODEL,
      attemptId: input.attemptId,
      ...metadata,
      payload,
      latencyMs: now() - startedAt,
    };
  } catch {
    return reject('invalid-response', true, 'invalid_structured_output');
  }
}

function failure(
  input: { attemptId: string },
  kind: Extract<ProviderAttemptResult, { ok: false }>['kind'],
  retryable: boolean,
  startedAt: number,
  now: () => number,
  detailCode?: string,
): Extract<ProviderAttemptResult, { ok: false }> {
  return {
    ok: false,
    provider: 'groq',
    model: GROQ_MODEL,
    attemptId: input.attemptId,
    kind,
    retryable,
    ...(detailCode ? { detailCode } : {}),
    latencyMs: now() - startedAt,
  };
}

import { decodeCognition } from '../domain';
import type { ResidentId } from '../../../../src/lib/habitat/residents';
import type { CognitionJob, JsonValue, ProviderAttemptResult, RouterResult, RuntimeConfig } from '../contracts';
import { PROVIDER_RETRY_MS, type QuotaMaximum, type QuotaReservationDecision, SqlQuotaLedger } from '../quota';
import { GROQ_MODEL, runGroq } from './groq';
import { estimateTokens } from './shared';
import { estimateGroqInputTokens } from './groq-token-estimate';
import {
  estimateWorkersAINeurons,
  isWorkersAIModel,
  runWorkersAI,
  workersAIInput,
  type WorkersAIRunner,
} from './workers-ai';

export async function routeCognition(input: {
  ai: WorkersAIRunner;
  groqApiKey?: string;
  config: RuntimeConfig;
  job: CognitionJob;
  attemptOrdinal: number;
  quota: SqlQuotaLedger;
  now?: () => number;
  groqFetch?: typeof fetch;
  validatePayload?: (payload: JsonValue) => boolean;
  canDispatch?: () => boolean;
}): Promise<RouterResult> {
  const now = input.now ?? Date.now;
  // Configuration is validated at startup, but injected/stale callers must
  // also fail closed before reserving quota or dispatching any fallback.
  if (!isWorkersAIModel(input.config.WORKERS_AI_MODEL)) {
    return { status: 'rejected', reasons: [{ ok: false, provider: 'workers-ai',
      model: input.config.WORKERS_AI_MODEL, attemptId: `${input.job.jobId}:workers-ai:${input.attemptOrdinal}`,
      kind: 'policy-blocked', retryable: false, detailCode: 'model_not_allowed', latencyMs: 0 }] };
  }
  const canRetryInvalid = (provider: ProviderAttemptResult['provider']) =>
    // Older injected ledgers have no accessor. Production SQL counts actual
    // submissions, including an ambiguous response, rather than alarm wakes.
    (input.quota.dispatchedCount?.(input.job.jobId, provider) ?? input.attemptOrdinal) < 2;
  const validate = input.validatePayload ?? ((payload: JsonValue) => Boolean(decodeCognition(input.job.subjects[0]!.id as ResidentId, payload)));
  const validateResult = (result: ProviderAttemptResult): ProviderAttemptResult => {
    if (result.usage) input.quota.settle(result.attemptId, result.usage, now());
    let valid = true;
    if (result.ok) {
      try { valid = validate(result.payload); } catch { valid = false; }
    }
    if (result.ok && !valid) {
      return { ok: false, provider: result.provider, model: result.model, attemptId: result.attemptId,
        kind: 'invalid-response', retryable: canRetryInvalid(result.provider),
        detailCode: input.validatePayload ? 'invalid_cognition_payload' : 'invalid_domain_intent',
        usage: result.usage, ...(result.providerRequestId ? { providerRequestId: result.providerRequestId } : {}), latencyMs: result.latencyMs };
    }
    if (!result.ok && result.kind === 'invalid-response') return { ...result, retryable: canRetryInvalid(result.provider) };
    return result;
  };
  const recordResult = (result: ProviderAttemptResult): ProviderAttemptResult => {
    const readyAt = input.quota.recordOutcome(result, now());
    return !result.ok && result.retryable && readyAt !== undefined
      ? { ...result, retryAtMs: Math.max(result.retryAtMs ?? 0, readyAt) } : result;
  };
  const reasons: ProviderAttemptResult[] = [];
  const cancelled = (provider: ProviderAttemptResult['provider'], model: string, attemptId: string): RouterResult => ({
    status: 'rejected',
    reasons: [...reasons, { ok: false, provider, model, attemptId, kind: 'rejected',
      retryable: false, detailCode: 'control_revision_changed', latencyMs: 0 }],
  });

  const workersAttemptId = `${input.job.jobId}:workers-ai:${input.attemptOrdinal}`;
  const workersPromptTokens = estimateTokens(JSON.stringify(workersAIInput(input.job, input.config.WORKERS_AI_MODEL)));
  const workersMaximum: QuotaMaximum = {
    requests: 1,
    inputTokens: workersPromptTokens,
    outputTokens: input.job.maxOutputTokens,
    neurons: estimateWorkersAINeurons(input.config.WORKERS_AI_MODEL, workersPromptTokens, input.job.maxOutputTokens),
  };
  // Keep this guard, reservation and dispatch synchronous: control cannot
  // interleave until the provider await. A paused job creates no reservation.
  if (input.canDispatch?.() === false) return cancelled('workers-ai', input.config.WORKERS_AI_MODEL, workersAttemptId);
  const workersReservation = input.quota.reserve(
    workersAttemptId,
    'workers-ai',
    workersMaximum,
    now(),
    input.job.jobId,
  );
  if (workersReservation.allowed) {
    input.quota.markDispatched(workersAttemptId, now());
    const result = recordResult(validateResult(await runWorkersAI({
      ai: input.ai,
      job: input.job,
      attemptId: workersAttemptId,
      model: input.config.WORKERS_AI_MODEL,
      now,
    })));
    if (result.ok) {
      return { status: 'completed', result, attempts: [...reasons, result] };
    }
    reasons.push(result);
  } else {
    reasons.push(quotaFailure('workers-ai', input.config.WORKERS_AI_MODEL, workersAttemptId, workersReservation));
    if (workersReservation.reason === 'duplicate') return { status: 'rejected', reasons };
  }

  const groqAttemptId = `${input.job.jobId}:groq:${input.attemptOrdinal}`;
  // Re-check after the primary await, before reserving or sending fallback.
  if (input.canDispatch?.() === false) return cancelled('groq', input.config.GROQ_MODEL, groqAttemptId);
  if (!input.groqApiKey) {
    const missingKey: Extract<ProviderAttemptResult, { ok: false }> = {
      ok: false,
      provider: 'groq',
      model: GROQ_MODEL,
      attemptId: groqAttemptId,
      kind: 'misconfigured',
      retryable: false,
      detailCode: 'missing_api_key',
      latencyMs: 0,
    };
    reasons.push(missingKey);
    return deferredOrRejected(reasons, now());
  }

  const groqMaximum: QuotaMaximum = {
    requests: 1,
    inputTokens: await estimateGroqInputTokens(input.job, input.config.GROQ_MODEL),
    outputTokens: input.job.maxOutputTokens,
    neurons: 0,
  };
  // Lazy tokenizer initialization is an await point. Recheck control, then keep
  // reservation and dispatch synchronous so a pause cannot leak a submission.
  if (input.canDispatch?.() === false) return cancelled('groq', input.config.GROQ_MODEL, groqAttemptId);
  const groqReservation = input.quota.reserve(
    groqAttemptId,
    'groq',
    groqMaximum,
    now(),
    input.job.jobId,
  );
  if (groqReservation.allowed) {
    input.quota.markDispatched(groqAttemptId, now());
    const result = recordResult(validateResult(await runGroq({
      apiKey: input.groqApiKey,
      job: input.job,
      attemptId: groqAttemptId,
      model: input.config.GROQ_MODEL,
      ...(input.groqFetch ? { fetcher: input.groqFetch } : {}),
      now,
    })));
    if (result.ok) {
      return { status: 'completed', result, attempts: [...reasons, result] };
    }
    reasons.push(result);
  } else {
    reasons.push(quotaFailure('groq', GROQ_MODEL, groqAttemptId, groqReservation));
  }

  return deferredOrRejected(reasons, now());
}

function deferredOrRejected(reasons: ProviderAttemptResult[], nowMs: number): RouterResult {
  const retryable = reasons.filter(
    (reason): reason is Extract<ProviderAttemptResult, { ok: false }> => !reason.ok && reason.retryable,
  );
  if (retryable.length === 0) return { status: 'rejected', reasons };
  const firstProviderReadyAtMs = Math.min(
    ...retryable.map((reason) => reason.retryAtMs ?? nowMs + PROVIDER_RETRY_MS),
  );
  const retryAtMs = Math.max(nowMs + 1_000, firstProviderReadyAtMs);
  return { status: 'deferred', retryAtMs, reasons };
}

function quotaFailure(
  provider: 'workers-ai' | 'groq',
  model: string,
  attemptId: string,
  decision: Exclude<QuotaReservationDecision, { allowed: true }>,
): Extract<ProviderAttemptResult, { ok: false }> {
  return {
    ok: false,
    provider,
    model,
    attemptId,
    kind: decision.reason === 'duplicate' || decision.reason === 'attempt-limit' ? 'rejected'
      : decision.reason === 'circuit-open' ? 'unavailable' : 'quota-exhausted',
    retryable: decision.reason !== 'duplicate' && decision.reason !== 'attempt-limit' && decision.limit !== 'request-size',
    retryAtMs: decision.retryAtMs,
    detailCode: decision.reason === 'attempt-limit' ? 'provider_attempt_limit'
      : decision.reason === 'duplicate' ? 'duplicate_attempt' : decision.reason === 'circuit-open'
      ? 'provider_circuit_open' : `local_${decision.limit ?? 'quota'}_limit`,
    latencyMs: 0,
  };
}

import { jsonValueSchema, type JsonValue, type ProviderUsage } from '../contracts';

export function estimateTokens(text: string): number {
  // UTF-8 bytes are a deliberately conservative upper bound for the byte-fallback
  // tokenizers used by the configured models. The fixed margin is an explicit
  // allowance for framing, not a measured server-side prompt count.
  return 128 + new TextEncoder().encode(text).byteLength;
}

export function parseStructuredPayload(value: unknown): JsonValue {
  // Strip only a complete leading reasoning wrapper. Never mine arbitrary
  // prose or unfinished reasoning for a JSON object that could be unintended.
  const content = typeof value === 'string'
    ? value.trim().replace(/^<think>[\s\S]*?<\/think>\s*/, '') : value;
  const decoded = typeof content === 'string' ? JSON.parse(content) : content;
  const payload = jsonValueSchema.parse(decoded);
  if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new TypeError('structured output must be a JSON object');
  }
  return payload;
}

export function sanitizeUsage(usage: {
  prompt_tokens?: unknown;
  completion_tokens?: unknown;
  total_tokens?: unknown;
  completion_tokens_details?: { reasoning_tokens?: unknown } | null;
} | null | undefined): ProviderUsage {
  const result: ProviderUsage = {};
  if (isUsageInteger(usage?.prompt_tokens)) {
    result.inputTokens = usage.prompt_tokens;
  }
  if (isUsageInteger(usage?.completion_tokens)) {
    result.outputTokens = usage.completion_tokens;
  }
  if (isUsageInteger(usage?.total_tokens)) {
    result.totalTokens = usage.total_tokens;
  }
  if (isUsageInteger(usage?.completion_tokens_details?.reasoning_tokens)) {
    result.reasoningTokens = usage.completion_tokens_details.reasoning_tokens;
  }
  if ([usage?.prompt_tokens, usage?.completion_tokens, usage?.total_tokens,
    usage?.completion_tokens_details?.reasoning_tokens].some((value) => value !== undefined && !isUsageInteger(value))) {
    result.incomplete = true;
  }
  return result;
}

export function isUsageInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

/** Missing, fractional or contradictory usage never authorizes a refund. */
export function hasCompleteTokenUsage(usage: ProviderUsage): usage is ProviderUsage & { inputTokens: number; outputTokens: number } {
  return usage.incomplete !== true && isUsageInteger(usage.inputTokens) && isUsageInteger(usage.outputTokens)
    && Number.isSafeInteger(usage.inputTokens + usage.outputTokens)
    && (usage.totalTokens === undefined || (isUsageInteger(usage.totalTokens)
      && usage.totalTokens === usage.inputTokens + usage.outputTokens))
    && (usage.reasoningTokens === undefined || (isUsageInteger(usage.reasoningTokens)
      && usage.reasoningTokens <= usage.outputTokens));
}

export function errorCode(error: unknown): string | undefined {
  if (typeof error !== 'object' || error === null) return undefined;
  const candidate = error as { code?: unknown; name?: unknown };
  if (typeof candidate.code === 'string') return candidate.code.slice(0, 80);
  if (typeof candidate.name === 'string') return candidate.name.slice(0, 80);
  return undefined;
}

