import type { CognitionJob, ProviderAttemptResult } from '../contracts';
import { errorCode, hasCompleteTokenUsage, parseStructuredPayload, sanitizeUsage } from './shared';
import { withProviderDeadline } from './deadline';

export const WORKERS_AI_MODEL = '@cf/qwen/qwen3-30b-a3b-fp8' as const;
export const GEMMA_WORKERS_AI_MODEL = '@cf/google/gemma-4-26b-a4b-it' as const;
export const OSS_WORKERS_AI_MODEL = '@cf/openai/gpt-oss-120b' as const;
export type WorkersAIModel = typeof WORKERS_AI_MODEL | typeof GEMMA_WORKERS_AI_MODEL | typeof OSS_WORKERS_AI_MODEL;
export const WORKERS_AI_TIMEOUT_MS = 45_000;

export type WorkersAIRunner = {
  run(model: WorkersAIModel, input: unknown): Promise<unknown>;
};

export function isWorkersAIModel(model: string): model is WorkersAIModel {
  return model === WORKERS_AI_MODEL || model === GEMMA_WORKERS_AI_MODEL || model === OSS_WORKERS_AI_MODEL;
}

type WorkersAIResponse = {
  response?: unknown;
  choices?: Array<{ finish_reason?: string; message?: { content?: unknown } }>;
  usage?: {
    prompt_tokens?: unknown;
    completion_tokens?: unknown;
    total_tokens?: unknown;
    completion_tokens_details?: { reasoning_tokens?: unknown } | null;
    neurons?: unknown;
  };
};

function classifyWorkersAIError(error: unknown): {
  kind: Extract<ProviderAttemptResult, { ok: false }>['kind'];
  retryable: boolean;
} {
  const code = errorCode(error)?.toLowerCase() ?? '';
  const message = error instanceof Error ? error.message.toLowerCase() : '';
  const detail = `${code} ${message}`;

  if (code === 'providertimeout') return { kind: 'timeout', retryable: true };

  if (/rate.?limit|too many requests|429/.test(detail)) return { kind: 'rate-limited', retryable: true };
  if (detail.includes('quota') || detail.includes('10040')) {
    return { kind: 'quota-exhausted', retryable: true };
  }
  if (detail.includes('auth') || detail.includes('permission') || detail.includes('forbidden')) {
    return { kind: 'authentication', retryable: false };
  }
  if (detail.includes('model') || detail.includes('binding')) {
    return { kind: 'misconfigured', retryable: false };
  }
  return { kind: 'unavailable', retryable: true };
}

/** The live provider and isolated end-to-end experiment must use the same
 * prompt, schema framing, output cap and deterministic sampling seed. */
export function workersAIInput(job: CognitionJob, model: WorkersAIModel = WORKERS_AI_MODEL) {
  if (!isWorkersAIModel(model)) throw new Error('model_not_allowed');
  if (model === GEMMA_WORKERS_AI_MODEL || model === OSS_WORKERS_AI_MODEL) {
    return {
      messages: [
        { role: 'system', content: job.prompt.system },
        { role: 'user', content: job.prompt.user },
      ],
      max_completion_tokens: job.maxOutputTokens,
      temperature: 0.3,
      seed: stableSeed(job.jobId),
      stream: false,
      ...(model === GEMMA_WORKERS_AI_MODEL ? { chat_template_kwargs: { enable_thinking: false } }
        : { reasoning_effort: 'low' }),
      response_format: { type: 'json_schema', json_schema: {
        name: job.outputContract.name, schema: job.outputContract.jsonSchema, strict: true,
      } },
    };
  }
  // Preserve this historical Qwen payload, including the default argument,
  // so isolated replay tooling can still reconstruct its original requests.
  const society = job.outputContract.name === 'society_turn';
  return {
    messages: [
      { role: 'system', content: society ? job.prompt.system : `${job.prompt.system}\nOutput JSON Schema: ${JSON.stringify(job.outputContract.jsonSchema)}` },
      // Qwen's documented soft switch leaves the bounded budget for the JSON.
      { role: 'user', content: `${job.prompt.user}\n/no_think` },
    ],
    max_tokens: job.maxOutputTokens,
    temperature: 0.3,
    seed: stableSeed(job.jobId),
    ...(society ? { response_format: { type: 'json_schema', json_schema: job.outputContract.jsonSchema } } : {}),
  };
}

export async function runWorkersAI(input: {
  ai: WorkersAIRunner;
  job: CognitionJob;
  attemptId: string;
  model: string;
  now?: () => number;
}): Promise<ProviderAttemptResult> {
  const now = input.now ?? Date.now;
  const startedAt = now();

  if (!isWorkersAIModel(input.model)) {
    return {
      ok: false,
      provider: 'workers-ai',
      model: input.model,
      attemptId: input.attemptId,
      kind: 'policy-blocked',
      retryable: false,
      detailCode: 'model_not_allowed',
      latencyMs: 0,
    };
  }

  try {
    const raw = (await withProviderDeadline(input.ai.run(input.model, workersAIInput(input.job, input.model)), WORKERS_AI_TIMEOUT_MS)) as WorkersAIResponse;

    // Qwen now returns the OpenAI chat-completion envelope, unlike older
    // Workers AI models. Reading only `response` discarded every valid thought.
    const usage = sanitizeUsage(raw?.usage);
    const reported = raw?.usage?.neurons;
    if (reported !== undefined && (typeof reported !== 'number' || !Number.isFinite(reported)
      || reported < 0 || reported > Number.MAX_SAFE_INTEGER)) usage.incomplete = true;
    if (hasCompleteTokenUsage(usage)) {
      const priced = estimateWorkersAINeurons(input.model, usage.inputTokens, usage.outputTokens);
      // A provider's complete metered amount can raise accounting; it never
      // authorizes a larger refund than the known tariff on reported tokens.
      usage.neurons = typeof reported === 'number'
        ? Math.max(priced, Math.ceil(reported)) : priced;
    }
    const choice = raw?.choices?.[0];
    if (choice?.finish_reason === 'length') {
      return {
        ok: false, provider: 'workers-ai', model: input.model,
        attemptId: input.attemptId, kind: 'invalid-response', retryable: true,
        detailCode: 'output_truncated', usage, latencyMs: now() - startedAt,
      };
    }
    let payload;
    try {
      payload = parseStructuredPayload(choice?.message?.content ?? raw?.response);
    } catch {
      return { ok: false, provider: 'workers-ai', model: input.model, attemptId: input.attemptId,
        kind: 'invalid-response', retryable: true, detailCode: 'invalid_structured_output', usage, latencyMs: now() - startedAt };
    }

    return {
      ok: true,
      provider: 'workers-ai',
      model: input.model,
      attemptId: input.attemptId,
      payload,
      usage,
      latencyMs: now() - startedAt,
    };
  } catch (error) {
    const classification = classifyWorkersAIError(error);
    const detailCode = errorCode(error);
    return {
      ok: false,
      provider: 'workers-ai',
      model: input.model,
      attemptId: input.attemptId,
      ...classification,
      ...(detailCode ? { detailCode } : {}),
      latencyMs: now() - startedAt,
    };
  }
}

export function estimateQwenNeurons(inputTokens: number, outputTokens: number): number {
  return estimateWorkersAINeurons(WORKERS_AI_MODEL, inputTokens, outputTokens);
}

/** Current rates for new reservations/results only; stored ledger usage is
 * already settled and must never be repriced after a configuration change. */
export function estimateWorkersAINeurons(model: WorkersAIModel, inputTokens: number, outputTokens: number): number {
  if (!isWorkersAIModel(model)) throw new Error('model_not_allowed');
  const rates = model === OSS_WORKERS_AI_MODEL ? { input: 31_818, output: 68_182 }
    : model === GEMMA_WORKERS_AI_MODEL ? { input: 9_091, output: 27_273 } : { input: 4_625, output: 30_475 };
  return Math.ceil((inputTokens * rates.input + outputTokens * rates.output) / 1_000_000);
}

function stableSeed(value: string): number {
  let hash = 2_166_136_261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16_777_619);
  }
  return (hash >>> 0) || 1;
}

import { applySocietyTurn, applySocietyChoice, applyCapabilityChoice } from '../../../src/lib/habitat/society/index';

/** A saved job keeps the grammar it was issued with. New prompts must never
 * reinterpret an outstanding response, and unknown versions fail closed. */
export function applySocietyProtocol(version: number, ...args: Parameters<typeof applySocietyTurn>) {
  if (version === 1) return applySocietyTurn(...args);
  if (version === 2) return applySocietyChoice(...args);
  if (version === 3) return applyCapabilityChoice(...args);
  return { ok: false, code: 'unsupported_society_contract', state: args[0], world: args[1] };
}

import { createHash } from 'node:crypto';
import { RESIDENTS, RESIDENT_BY_ID, type ResidentId } from '../../../src/lib/habitat/residents';
import { prepareSocietyTurn, type SocietyState, type PreparedTurn } from '../../../src/lib/habitat/society/index';
import { capabilityChoiceJsonSchema, toCapabilityAction } from '../../../src/lib/habitat/society/capabilities';
import { SOCIETY_SYSTEM } from '../../../src/lib/habitat/society/instructions';
import type { WorldState } from '../../../src/lib/habitat/engine/state';
import { cognitionJobSchema, type CognitionJob, type JsonValue } from './contracts';

export const COGNITION_CADENCE_MS = 3 * 60_000;
export const COGNITION_REVIEW_MS = 6 * 60 * 60_000;
export const COGNITION_FAILURE_BACKOFF_MS = 30 * 60_000;

/** The grammar already carries these exact IDs/ranges. Do not charge the
 * provider twice for them; preserve all narrative evidence and its references. */
function withoutGrammarDuplicates(turn: PreparedTurn, schema: Record<string, unknown>): PreparedTurn {
  const split = turn.prompt.lastIndexOf('\n{');
  if (split < 0) throw new RangeError('Missing resident context');
  const context = JSON.parse(turn.prompt.slice(split + 1)) as {
    public: Record<string, unknown>; affordances: Record<string, unknown>; omitted: Record<string, unknown>; refIds?: unknown;
  };
  delete context.public.roomIds;
  const people = (schema.$defs as { person?: { enum: string[] } }).person?.enum
    ?? [turn.actor, ...((schema.properties as { message?: { properties: { to: { enum: string[] } } } }).message?.properties.to.enum ?? [])];
  if (Array.isArray(context.public.people) && people && context.public.people.every((id) => people.includes(id))) delete context.public.people;
  for (const key of ['allowedRecipientIds', 'mayMessage', 'physicalVerbs', 'workUnits', 'loanDueDayRange', 'workDueWatchRange', 'ownMinimumWorkDue', 'verbMeaning', 'agreements']) delete context.affordances[key];
  // Fixed verb meanings live in the stable SYSTEM message. Compact this
  // variable recipe table without removing quantities, prerequisites or effects.
  if (Array.isArray(context.affordances.workExamples)) {
    context.affordances.workExamples = { columns: ['verb', 'at', 'available', 'needs', 'produces'],
      rows: context.affordances.workExamples.map((entry: Record<string, unknown>) => {
        const action = toCapabilityAction(entry as { verb: string; at: string });
        return [action?.verb ?? entry.verb, entry.at, entry.available, entry.needs, entry.produces];
      }) };
  }
  // Empty sections add no evidence. Keep ownProject/conversation explicit so
  // first contact cannot be mistaken for an already-running conversation.
  const fields = context as Record<string, unknown>;
  // Show a stored action using the same vocabulary as the new choices, while
  // leaving persisted plans, agreements and historic evidence untouched.
  const ownProject = fields.ownProject as { steps?: Array<{ intent: { verb: string; room?: string }; at: string | null }> } | null;
  for (const step of ownProject?.steps ?? []) {
    const action = toCapabilityAction({ ...step.intent, ...(step.at ? { at: step.at } : {}) });
    if (action) step.intent.verb = action.verb;
  }
  for (const key of ['openOffers', 'commitments']) {
    for (const item of (fields[key] ?? []) as Array<{ terms?: { kind: string; verb?: string; room?: string } }>) {
      if (item.terms?.kind === 'work' && item.terms.verb) {
        const action = toCapabilityAction({ verb: item.terms.verb, ...(item.terms.room ? { room: item.terms.room } : {}) });
        if (action) item.terms.verb = action.verb;
      }
    }
  }
  for (const key of ['ownKnowledge', 'sharedHistory', 'memories', 'ownHistory', 'openOffers', 'commitments', 'receivables']) {
    if (Array.isArray(fields[key]) && (fields[key] as unknown[]).length === 0) delete fields[key];
  }
  const feelings = fields.ownFeelings as { towards?: unknown[] } | undefined;
  if (feelings?.towards?.length === 0) delete fields.ownFeelings;
  if (Array.isArray(context.affordances.repayments) && context.affordances.repayments.length === 0) delete context.affordances.repayments;
  if (context.omitted.workExampleCount) {
    context.omitted.workRecipes = context.omitted.workExampleCount;
    delete context.omitted.workExampleCount;
    delete context.omitted.workExamples;
  }
  delete context.refIds;
  context.omitted = Object.fromEntries(Object.entries(context.omitted).filter(([, value]) => value !== 0 && value !== false));
  // The provider receives the full instructions once, in the system role.
  // PreparedTurn keeps the same context/evidence binding for durable replay.
  const actor = RESIDENT_BY_ID[turn.actor];
  const recipients = (schema.properties as { message?: { properties: { to: { enum: ResidentId[] } } } }).message?.properties.to.enum ?? [];
  const directory = recipients.map((id) => `${id}=${RESIDENT_BY_ID[id].name}`).join('; ');
  const prompt = `You are ${actor.name} (${actor.id}). Speak and choose in the first person as ${actor.name}.\nAvailable recipients: ${directory || 'none'}\nCurrent information:\n${JSON.stringify(context)}`;
  const promptBytes = new TextEncoder().encode(prompt).length;
  // Essential ongoing plans/agreements may exceed the compact 4200 target.
  // Keep them for Workers AI; Groq's actual quota guard can reject a large job.
  return { ...turn, prompt, promptBytes, contextOverflow: promptBytes > 6500 };
}

/** Alternate scarce slots between overdue individual reviews and replies. An
 * unanswered voice cannot monopolize the queue; successful recent talk counts
 * as that individual's review. Selection reads no other mind's private prose. */
export function nextSocietyActor(state: SocietyState, nowMs: number, sequence: number,
  occupied: ReadonlySet<ResidentId> = new Set()): ResidentId | undefined {
  const eligible = RESIDENTS.map(({ id }) => id).filter((id) => {
    const m = state.minds[id];
    return !occupied.has(id) && (m.lastAttemptAtMs === null || m.lastAttemptAtMs <= (m.lastSuccessAtMs ?? -1)
      || nowMs - m.lastAttemptAtMs >= COGNITION_FAILURE_BACKOFF_MS);
  });
  const waiting = state.conversations.filter((c) => c.status === 'open' && c.expiresAtMs > nowMs
    && c.nextSpeaker && eligible.includes(c.nextSpeaker))
    .sort((a, b) => (a.turns.at(-1)?.atMs ?? a.createdAtMs) - (b.turns.at(-1)?.atMs ?? b.createdAtMs));
  const overdue = eligible.filter((id) => state.minds[id].lastSuccessAtMs === null
    || nowMs - state.minds[id].lastSuccessAtMs! >= COGNITION_REVIEW_MS
    || state.minds[id].memories.some((m) => m.kind === 'observation' && m.createdAtMs > state.minds[id].lastSuccessAtMs!))
    .sort((a, b) => (state.minds[a].lastSuccessAtMs ?? -1) - (state.minds[b].lastSuccessAtMs ?? -1)
      || (state.minds[a].lastAttemptAtMs ?? -1) - (state.minds[b].lastAttemptAtMs ?? -1) || a.localeCompare(b));
  return sequence % 2 === 0 ? overdue[0] ?? waiting[0]?.nextSpeaker ?? undefined
    : waiting[0]?.nextSpeaker ?? overdue[0];
}

export function prepareSocietyJob(input: { state: SocietyState; world: WorldState; actor: ResidentId;
  nowMs: number; sequence: number; generation: number; worldRevision: number; habitatId: string;
}): { turn: PreparedTurn; job: CognitionJob } {
  const rawTurn = prepareSocietyTurn(input.state, input.world, input.actor, {
    nowMs: input.nowMs, sequence: input.sequence, generation: input.generation, ttlMs: 900_000, maxPromptBytes: 6500,
  });
  const schema = capabilityChoiceJsonSchema(input.state, input.world, rawTurn) as JsonValue;
  const turn = withoutGrammarDuplicates(rawTurn, schema as Record<string, unknown>);
  const job = cognitionJobSchema.parse({
    schemaVersion: 1, jobId: `${input.habitatId}:mind:${turn.id}:g:${input.generation}`,
    habitatId: input.habitatId, origin: { kind: 'alarm', runId: `society:${input.sequence}` },
    cause: { worldRevision: input.worldRevision, simTime: { day: input.world.day, minute: (input.world.watch - 1) * 360 } },
    kind: 'society_turn', subjects: [{ kind: 'resident', id: input.actor }],
    pressure: input.world.bodies[input.actor].pressure / 100, createdAtMs: input.nowMs,
    prompt: { system: SOCIETY_SYSTEM, user: turn.prompt },
    outputContract: { name: 'society_turn', version: 3,
      schemaHash: `sha256:${createHash('sha256').update(JSON.stringify(schema)).digest('hex')}`, jsonSchema: schema },
    maxOutputTokens: 1024,
  });
  return { turn, job };
}
